-- 12-week sport programs (GRIZZ, 2026-10-23): for each sport that has an
-- off-season program, a separate Strength, Endurance and Speed program. 27
-- built-ins, three 4-week blocks each (weeks 4 and 8 recovery, week 12 a test
-- week). The helper upserts one program and its exercises from a template, so
-- this migration can be re-run safely.

create or replace function public.add_sport_block(p_name text, p_description text, p_nutrition text, p_warm_up text, p_titles jsonb, p_tpl jsonb)
returns void
language plpgsql
set search_path = public
as $f$
declare
  prog uuid;
  titles text[] := '{}';
  w int;
  k int;
  dd int;
  ph text;
  rk text;
  half boolean;
  hv boolean;
  wp int;
  tag text;
  d text;
  r jsonb;
  src jsonb;
  i int;
  n int;
begin
  for w in 1..12 loop
    k := (w + 3) / 4;
    ph := 'p' || k;
    tag := case w when 4 then ' (recovery week)' when 8 then ' (recovery week)' when 12 then ' (test week)' else '' end;
    for dd in 1..7 loop
      titles := titles || ((p_titles ->> dd::text) || case when p_tpl -> ph ? dd::text then tag else '' end);
    end loop;
  end loop;
  select id into prog from public.programs where trainer_id is null and name = p_name limit 1;
  if prog is null then
    insert into public.programs (trainer_id, name, kind, place, weeks, description, nutrition, warm_up, day_titles)
    values (null, p_name, 'weekly', 'gym', 12, p_description, p_nutrition, p_warm_up, titles)
    returning id into prog;
  else
    update public.programs set description = p_description, nutrition = p_nutrition, warm_up = p_warm_up, day_titles = titles
    where id = prog;
  end if;
  for w in 1..12 loop
    k := (w + 3) / 4;
    ph := 'p' || k;
    rk := 'r' || k;
    half := (w % 4 = 0);
    wp := case when half then 1 else w - (k - 1) * 4 end;
    for d in select jsonb_object_keys(p_tpl -> ph) loop
      src := p_tpl -> ph -> d;
      hv := half;
      if half and (p_tpl -> rk) ? d then
        src := p_tpl -> rk -> d;
        hv := false;
      end if;
      i := 0;
      for r in select * from jsonb_array_elements(src) loop
        i := i + 1;
        n := (r->>1)::int;
        n := case when hv then greatest(1, ceil(n / 2.0)::int) when half then n when (r->>4)::boolean then greatest(n, least(6, n + wp - 1)) else n end;
        update public.program_exercises
        set exercise_id = (select e.id from public.exercises e where e.name = r->>0 order by e.sort_order limit 1),
            exercise_name = r->>0, sets = n, reps = r->>2, rest_seconds = (r->>3)::smallint, kind = 'exercise'
        where program_id = prog and week_number = w and day_number = d::smallint and sort_order = i;
        if not found then
          insert into public.program_exercises (program_id, week_number, day_number, sort_order, exercise_id, exercise_name, sets, reps, rest_seconds, kind)
          values (prog, w, d::smallint, i,
            (select e.id from public.exercises e where e.name = r->>0 order by e.sort_order limit 1),
            r->>0, n, r->>2, (r->>3)::smallint, 'exercise');
        end if;
      end loop;
      if exists (select 1 from public.program_exercises pe where pe.program_id = prog and pe.week_number = w
                 and pe.day_number = d::smallint and pe.sort_order > i) then
        raise exception '% week % day % has more rows than the template', p_name, w, d;
      end if;
    end loop;
  end loop;
  if exists (select 1 from public.program_exercises pe where pe.program_id = prog and pe.exercise_id is null) then
    raise exception 'an exercise in % is not in the library', p_name;
  end if;
end $f$;
revoke execute on function public.add_sport_block(text, text, text, text, jsonb, jsonb) from public, anon, authenticated;
revoke all on function public.add_sport_block(text, text, text, text, jsonb, jsonb) from public, anon, authenticated;

select public.add_sport_block('12-Week Strength – Soccer', 'For Soccer: a 12-week strength program. Soccer players need strong legs and hips for sprinting, kicking and cutting, and hamstrings and groin muscles that do not tear. Nordic curls protect the hamstrings, hip adduction the groin, and calf and shin work the lower leg. Four strength sessions a week (Monday lower body, Tuesday upper body, Thursday hips and hamstrings, Friday upper body and trunk) train every muscle twice a week, with an easy zone 2 and mobility session on Wednesday, your sport or rest on Saturday and a full rest on Sunday. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds muscle and tendon strength at 8-10 reps with sets going up each week. Block 2 (weeks 5-7) gets heavier at 4-6 reps. Block 3 (weeks 9-11) peaks strength at 3-5 reps with a few fast jumps or lifts on top. Weeks 4 and 8 are recovery weeks at half the sets so your body can absorb the work, and week 12 is a test week at half the sets: work up to your best clean set of 3-5 reps on the main lifts and stop when the bar slows or your form changes. No set goes to failure: stop each set with 1-2 good reps left, and add weight only when every rep is clean. There is no overhead pressing.', 'Strength is built in the kitchen as much as the gym: eat enough to recover and add muscle. Protein 1.6-2.2 g per kg of bodyweight a day, split over 4-5 meals (chicken, beef, fish, eggs, maas, yoghurt, beans). Carbs of 4-6 g/kg on heavy training days from rice, potatoes, sweet potato, pap, bread and fruit, and a bit less on rest days. Eat a carb-and-protein meal 2-3 hours before training and another within 2 hours after. Drink 35-40 ml of water per kg a day plus 500-750 ml per hour of training. Recovery weeks are not for dieting: keep eating. Sleep 8-9 hours: it''s when you get stronger.', 'RAMP warm-up, 10 minutes: 3-4 minutes easy bike, rower or skipping, then leg swings, hip circles, world''s greatest stretch and band pull-aparts, then 2-3 light ramp-up sets of your first lift before the working sets. Add weight only when every rep is clean.', '{"1":"Strength A: lower body","2":"Strength B: upper body","3":"Active recovery: zone 2 + mobility","4":"Strength C: hips & hamstrings","5":"Strength D: upper body & trunk","6":"Play your sport or rest","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Barbell Back Squat",3,"8-10",120,true],["Dumbbell Bulgarian Split Squat",3,"8-10 each leg",90,true],["Hip Adduction",3,"12-15",60,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Tibialis Raise",2,"15",45,false],["Pallof Press",3,"12-15 each side",60,false]],"2":[["Bench Press",3,"8-10",120,true],["Chest-Supported Row",3,"8-10",90,true],["Incline Dumbbell Press",3,"8-10",90,true],["Cable Seated Rope Face Pull",3,"12-15",60,false],["Hammer Curl",3,"12-15",60,false],["Cable Rope Pushdown",3,"12-15",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Trap Bar Deadlift",3,"8-10",120,true],["Hip Thrust",3,"8-10",90,true],["Nordic Hamstring Curl",2,"4-6, slow on the way down",120,true],["Cable Hip Abduction",3,"12-15",60,false],["Back Extension",3,"12-15",60,false],["Standing Calf Raise",3,"12-15",45,false],["Dead Bug",3,"12-15 each side",60,false]],"5":[["Pull-Up",3,"8-10",120,true],["Dumbbell Single-Arm Row",3,"8-10 each arm",90,true],["Neutral-Grip Dumbbell Bench Press",3,"8-10",90,true],["Dumbbell Rear-Delt Fly",3,"12-15",60,false],["Cable Wood Chopper",3,"12-15 each side",60,false],["Dumbbell Farmer''s Carry",2,"30 m",60,false]]},"p2":{"1":[["Barbell Back Squat",3,"4-6",180,true],["Dumbbell Bulgarian Split Squat",3,"6-8 each leg",120,false],["Hip Adduction",3,"10-12",60,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Tibialis Raise",2,"15-20",45,false],["Pallof Press",3,"10-12 each side",60,false]],"2":[["Bench Press",3,"4-6",180,true],["Chest-Supported Row",3,"6-8",120,false],["Incline Dumbbell Press",3,"6-8",120,false],["Cable Seated Rope Face Pull",3,"10-12",60,false],["Hammer Curl",3,"10-12",60,false],["Cable Rope Pushdown",3,"10-12",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Trap Bar Deadlift",3,"4-6",180,true],["Hip Thrust",3,"6-8",120,false],["Nordic Hamstring Curl",3,"5-6, slow on the way down",120,false],["Cable Hip Abduction",3,"10-12",60,false],["Back Extension",3,"10-12",60,false],["Standing Calf Raise",3,"10-12",45,false],["Dead Bug",3,"10-12 each side",60,false]],"5":[["Weighted Pull-Up",3,"4-6",180,true],["Dumbbell Single-Arm Row",3,"6-8 each arm",120,false],["Neutral-Grip Dumbbell Bench Press",3,"6-8",120,false],["Dumbbell Rear-Delt Fly",3,"10-12",60,false],["Cable Wood Chopper",3,"10-12 each side",60,false],["Dumbbell Farmer''s Carry",3,"30 m",60,false]]},"p3":{"1":[["Barbell Back Squat",4,"3-5",180,false],["Box Jump",3,"3, straight after each squat set. Step down, don''t jump down",90,false],["Dumbbell Bulgarian Split Squat",3,"5-6 each leg",120,false],["Hip Adduction",3,"8-10",60,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg, fast up",45,false],["Tibialis Raise",2,"20",45,false],["Pallof Press",3,"8-10 each side",60,false]],"2":[["Bench Press",4,"3-5",180,false],["Chest-Supported Row",3,"5-6",120,false],["Incline Dumbbell Press",3,"5-6",120,false],["Cable Seated Rope Face Pull",3,"8-10",60,false],["Hammer Curl",3,"8-10",60,false],["Cable Rope Pushdown",3,"8-10",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Trap Bar Deadlift",4,"3-5",180,false],["Hip Thrust",3,"5-6",120,false],["Nordic Hamstring Curl",3,"6, slow on the way down",120,false],["Cable Hip Abduction",3,"8-10",60,false],["Back Extension",3,"8-10",60,false],["Standing Calf Raise",3,"8-10, fast up",45,false],["Dead Bug",3,"8-10 each side",60,false]],"5":[["Weighted Pull-Up",4,"3-5",180,false],["Dumbbell Single-Arm Row",3,"5-6 each arm",120,false],["Neutral-Grip Dumbbell Bench Press",3,"5-6",120,false],["Dumbbell Rear-Delt Fly",3,"8-10",60,false],["Cable Wood Chopper",3,"8-10 each side",60,false],["Dumbbell Farmer''s Carry",3,"40 m",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Endurance – Soccer', 'For Soccer: a 12-week endurance program. Soccer is 90 minutes of jogging, walking and repeated sprints. The program builds a big aerobic base so you recover quickly between sprints, then threshold and high-intensity intervals, and finishes with repeated sprints. Each week has 6 sessions: Monday zone 2 base, Tuesday intervals, Wednesday a short full-body strength session to keep your strength and protect your joints, Thursday tempo or threshold work, Friday easy recovery and mobility, and a long easy session on Saturday. Sunday is full rest. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds the aerobic base with short, light intervals. Block 2 (weeks 5-7) adds threshold work. Block 3 (weeks 9-11) adds harder, sport-specific intervals. The easy sessions get a little longer each block, and the interval rounds go up each week. Weeks 4 and 8 are recovery weeks with shorter easy sessions and half the intervals and strength sets. Week 12 is a test week: easy sessions, then a steady hard test on Tuesday so you can see how far you have come. Zone 2 means an easy pace where you can still chat. The hard efforts are about 8-9 out of 10 and the easy ones feel truly easy: most of your gains come from the easy days.', 'Endurance runs on carbs and recovers on protein. Carbs of 5-8 g per kg of bodyweight a day on hard and long days from rice, potatoes, sweet potato, pap, bread, oats and fruit, and less on easy days. Protein 1.4-1.8 g per kg a day over 4-5 meals. On sessions longer than 75 minutes, take 30-60 g of carbs an hour (bananas, dates, sweets or a sports drink) and sip 500-750 ml of water an hour, more in the heat. Eat a carb-based meal 2-3 hours before and a carb-and-protein meal within 2 hours after. Do not train hungry on hard days. Sleep 8-9 hours.', 'Warm up for 8-10 minutes: easy movement at zone 1 for 5 minutes, then leg swings, hip circles and world''s greatest stretch, and 3-4 short pick-ups of 15 seconds before hard intervals. Finish every session with 5 minutes of easy movement.', '{"1":"Aerobic base: zone 2","2":"Intervals","3":"Strength maintenance (full body)","4":"Tempo and threshold","5":"Easy recovery + mobility","6":"Long session","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Treadmill Run",1,"30 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Running Intervals",5,"1 min at 8/10, 2 min easy jog between",120,true]],"3":[["Barbell Back Squat",2,"8-10",120,false],["Romanian Deadlift",2,"8-10",120,false],["Dumbbell Bulgarian Split Squat",2,"8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"40 sec",30,false]],"4":[["Treadmill Run",1,"25 min steady: comfortable pace, you can say a sentence",60,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Long Run",1,"40 min easy: zone 2, a pace where you can talk",60,false]]},"p2":{"1":[["Treadmill Run",1,"35 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Running Intervals",3,"4 min at 8/10, 3 min easy jog between",180,true]],"3":[["Barbell Back Squat",2,"6-8",120,false],["Romanian Deadlift",2,"6-8",120,false],["Dumbbell Bulgarian Split Squat",2,"6-8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false]],"4":[["Tempo Run",2,"10 min at 7/10: comfortably hard, 3 min easy between",180,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Long Run",1,"50 min easy: zone 2, a pace where you can talk",60,false]]},"p3":{"1":[["Treadmill Run",1,"40 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Running Intervals",4,"4 min at 9/10, 3 min easy jog between",180,false]],"3":[["Barbell Back Squat",2,"5-6",150,false],["Romanian Deadlift",2,"5-6",150,false],["Dumbbell Bulgarian Split Squat",2,"6 each leg",90,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false]],"4":[["Running Intervals",2,"6 x 30 m sprints with 20 sec between. 3 min between sets",180,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Long Run",1,"60 min easy: zone 2, a pace where you can talk",60,false]]},"r1":{"1":[["Treadmill Run",1,"18 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Long Run",1,"24 min easy: zone 2, a pace where you can talk",60,false]],"4":[["Treadmill Run",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r2":{"1":[["Treadmill Run",1,"21 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Long Run",1,"30 min easy: zone 2, a pace where you can talk",60,false]],"4":[["Treadmill Run",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r3":{"1":[["Treadmill Run",1,"24 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Long Run",1,"36 min easy: zone 2, a pace where you can talk",60,false]],"2":[["Running Intervals",1,"Test: 12 min at a steady hard pace. Note the distance you cover",60,false]],"4":[["Treadmill Run",1,"20 min easy: stay loose before your test",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Speed – Soccer', 'For Soccer: a 12-week speed program. Soccer speed is a quick first step, repeated sprints and sharp changes of direction. The program builds acceleration first, then top speed, then reactive sprinting and quick turns, with the hamstring and groin protection sprinters need. Monday is acceleration and lower body strength, Tuesday upper body and trunk, Wednesday easy zone 2 and mobility, Thursday top speed and change of direction, and Friday power and elastic strength. Saturday is your sport or rest and Sunday is full rest. Hard sprinting never comes on back-to-back days. It runs in three 4-week blocks. Block 1 (weeks 1-3) learns good mechanics and builds a base at 8 out of 10 effort, so tendons and hamstrings are ready. Block 2 (weeks 5-7) goes all-out on acceleration and adds fast, springy work. Block 3 (weeks 9-11) peaks with the fastest efforts and the most reactive work. Weeks 4 and 8 are recovery weeks at half the sets, and week 12 is a test week at half the sets: test a 20 m sprint and a broad jump (or your best sprint on the bike) and compare with week 1. Rest fully between sprints: speed work is quality, not tiring conditioning, so stop the session if your form slips or a hamstring feels tight. No set goes to failure, and depth jumps are from a low box only.', 'Speed needs fresh legs and a fed body. Protein 1.6-2.0 g per kg of bodyweight a day over 4-5 meals (chicken, beef, fish, eggs, maas, yoghurt, beans). Carbs of 4-6 g/kg a day from rice, potatoes, sweet potato, pap, bread and fruit, with a carb-based meal 2-3 hours before speed sessions so you are not running on empty. Drink 35-40 ml of water per kg a day. Do not diet hard during speed blocks: being under-fed slows you down and raises injury risk. Sleep 8-9 hours: speed is learned while you rest.', 'Full sprint warm-up, 15 minutes: 5 minutes easy jog or bike, then leg swings, hip circles, world''s greatest stretch, A-skips and B-skips, then 3-4 build-up runs or spin-ups, each a little faster, before the first all-out effort. Never sprint cold.', '{"3":"Active recovery: zone 2 + mobility","6":"Play your sport or rest","7":"Full rest","1":"Acceleration & lower body strength","2":"Upper body & trunk","4":"Top speed & change of direction","5":"Power & elastic strength"}'::jsonb, '{"p1":{"1":[["A-Skip",2,"20 m",60,false],["B-Skip",2,"20 m",60,false],["Wall Drive Drill",3,"3 x 5 sec, hold the lean and drive the knee",60,false],["Acceleration Sprint",5,"20 m at 8/10: smooth and fast, not all-out, walk back",90,true],["Barbell Back Squat",3,"5-6",150,true],["Hip Thrust",3,"8",90,false],["Nordic Hamstring Curl",2,"4-6, slow on the way down",120,true],["Single-Leg Standing Calf Raise",3,"12 each leg",45,false]],"2":[["Bench Press",3,"6-8",120,true],["Chest-Supported Row",3,"8",90,true],["Cable Seated Rope Face Pull",3,"12-15",45,false],["Pallof Press",3,"10 each side",45,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Flying Sprint",3,"20 m build-up then 10 m at 90%",150,false],["Ladder Quick Feet",3,"1 pass, fast and light",60,false],["Pro Agility Shuttle",3,"1 at 8/10, learn the turns",120,false],["Pogo Hops",3,"10, stiff and quick",60,false]],"5":[["Jump Squat",3,"5, bodyweight, land softly",90,false],["Box Jump",3,"3, step down",90,false],["Medicine Ball Slam",3,"8",60,false],["Medicine Ball Scoop Toss",3,"5, hips drive it",60,false],["Hip Thrust",3,"8",90,false],["Pallof Press",3,"10 each side",45,false]]},"p2":{"1":[["A-Skip",2,"20 m",60,false],["Wall Drive Drill",2,"3 x 5 sec fast",60,false],["Acceleration Sprint",6,"20 m all-out, walk back and rest fully",120,true],["Barbell Back Squat",3,"3-5",180,true],["Hip Thrust",3,"6, fast up",90,false],["Nordic Hamstring Curl",3,"5-6, slow on the way down",120,false],["Single-Leg Standing Calf Raise",3,"10 each leg",45,false]],"2":[["Bench Press",3,"4-6",150,true],["Chest-Supported Row",3,"6-8",120,false],["Medicine Ball Chest Pass",3,"6, fast",60,false],["Cable Seated Rope Face Pull",3,"12",45,false],["Pallof Press",3,"10 each side",45,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Flying Sprint",4,"20 m build-up then 20 m fast",180,false],["Pro Agility Shuttle",4,"1 all-out",120,false],["Crossover Run",3,"15 m each side",60,false],["Lateral Bound",3,"5 each side, stick it",60,false],["Single-Leg Hop",2,"5 each leg",60,false]],"5":[["Jump Squat",4,"4, light load, fast",90,false],["Box Jump",3,"3, step down",90,false],["Medicine Ball Slam",3,"6, hard",60,false],["Medicine Ball Scoop Toss",3,"5, hips drive it",60,false],["Single-Leg Hop",2,"5 each leg",60,false],["Pallof Press",3,"10 each side",45,false]]},"p3":{"1":[["A-Skip",2,"20 m",60,false],["Falling Start Sprint",4,"20 m all-out, lean and fall into it",120,true],["Acceleration Sprint",4,"20 m all-out, full rest",120,false],["Barbell Back Squat",4,"3",180,false],["Hip Thrust",3,"5, fast up",90,false],["Nordic Hamstring Curl",3,"6, slow on the way down",120,false],["Single-Leg Standing Calf Raise",3,"8 each leg, fast up",45,false]],"2":[["Bench Press",4,"3-5",150,false],["Chest-Supported Row",3,"5-6",120,false],["Medicine Ball Chest Pass",3,"5, hard",60,false],["Cable Seated Rope Face Pull",3,"12",45,false],["Pallof Press",3,"10 each side",45,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Flying Sprint",5,"20 m build-up then 20 m all-out",180,false],["Pro Agility Shuttle",4,"1 all-out",120,false],["Falling Start Sprint",3,"10 m all-out then stop under control",120,false],["Depth Jump",3,"4, from a low box (30-40 cm): step off, land and jump straight up",120,false],["Lateral Bound",3,"5 each side",60,false]],"5":[["Jump Squat",4,"3, light load, fast",90,false],["Broad Jump",3,"4, stick the landing",90,false],["Bounding",3,"30 m",90,false],["Medicine Ball Scoop Toss",3,"4, hips drive it",60,false],["Single-Leg Hop",2,"5 each leg",60,false],["Pallof Press",3,"10 each side",45,false]]}}'::jsonb);
select public.add_sport_block('12-Week Strength – Rugby', 'For Rugby: a 12-week strength program. Rugby needs big, strong legs and hips for scrums, rucks and tackles, a strong neck and upper back for contact, and hamstrings that hold up to sprinting. Neck work, rows and shrugs build the upper body for contact, and Nordic curls and hip adduction guard the hamstrings and groin. Four strength sessions a week (Monday lower body, Tuesday upper body, Thursday hips and hamstrings, Friday upper body and trunk) train every muscle twice a week, with an easy zone 2 and mobility session on Wednesday, your sport or rest on Saturday and a full rest on Sunday. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds muscle and tendon strength at 8-10 reps with sets going up each week. Block 2 (weeks 5-7) gets heavier at 4-6 reps. Block 3 (weeks 9-11) peaks strength at 3-5 reps with a few fast jumps or lifts on top. Weeks 4 and 8 are recovery weeks at half the sets so your body can absorb the work, and week 12 is a test week at half the sets: work up to your best clean set of 3-5 reps on the main lifts and stop when the bar slows or your form changes. No set goes to failure: stop each set with 1-2 good reps left, and add weight only when every rep is clean. There is no overhead pressing.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Strength – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Strength – Soccer'), '{"1":"Strength A: lower body","2":"Strength B: upper body","3":"Active recovery: zone 2 + mobility","4":"Strength C: hips & hamstrings","5":"Strength D: upper body & trunk","6":"Play your sport or rest","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Barbell Back Squat",3,"8-10",120,true],["Barbell Split Squat",3,"8-10 each leg",90,true],["Hip Adduction",3,"12-15",60,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Neck Curl",2,"15-20, light and slow",45,false],["Neck Extension",2,"15-20, light and slow",45,false]],"2":[["Bench Press",3,"8-10",120,true],["Bent-Over Barbell Row",3,"8-10",90,true],["Incline Dumbbell Press",3,"8-10",90,true],["Cable Seated Rope Face Pull",3,"12-15",60,false],["Barbell Shrug",3,"12-15",60,false],["Hammer Curl",3,"12-15",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Romanian Deadlift",3,"8-10",120,true],["Hip Thrust",3,"8-10",90,true],["Nordic Hamstring Curl",2,"4-6, slow on the way down",120,true],["Cable Hip Abduction",3,"12-15",60,false],["Back Extension",3,"12-15",60,false],["Pallof Press",3,"12-15 each side",60,false]],"5":[["Pull-Up",3,"8-10",120,true],["Dumbbell Single-Arm Row",3,"8-10 each arm",90,true],["Neutral-Grip Dumbbell Bench Press",3,"8-10",90,true],["Dumbbell Rear-Delt Fly",3,"12-15",60,false],["Cable Wood Chopper",3,"12-15 each side",60,false],["Dumbbell Farmer''s Carry",2,"30 m",60,false]]},"p2":{"1":[["Barbell Back Squat",3,"4-6",180,true],["Barbell Split Squat",3,"6-8 each leg",120,false],["Hip Adduction",3,"10-12",60,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Neck Curl",2,"15-20, light and slow",45,false],["Neck Extension",2,"15-20, light and slow",45,false]],"2":[["Bench Press",3,"4-6",180,true],["Bent-Over Barbell Row",3,"6-8",120,false],["Incline Dumbbell Press",3,"6-8",120,false],["Cable Seated Rope Face Pull",3,"10-12",60,false],["Barbell Shrug",3,"10-12",60,false],["Hammer Curl",3,"10-12",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec