 Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Trap Bar Deadlift",3,"4-6",180,true],["Hip Thrust",3,"6-8",120,false],["Nordic Hamstring Curl",3,"5-6, slow on the way down",120,false],["Cable Hip Abduction",3,"10-12",60,false],["Back Extension",3,"10-12",60,false],["Dead Bug",3,"10-12 each side",60,false]],"5":[["Weighted Pull-Up",3,"4-6",180,true],["Dumbbell Single-Arm Row",3,"6-8 each arm",120,false],["Push-Up",3,"6-8",120,false],["Cable External Rotation",3,"12 each arm",45,false],["Band High Face Pull",3,"10-12",60,false],["Dumbbell Wrist Curl",3,"10-12",60,false]]},"p3":{"1":[["Barbell Back Squat",4,"3-5",180,false],["Medicine Ball Rotational Throw",3,"4 each side, fast",60,false],["Dumbbell Lateral Lunge",3,"5-6 each side",120,false],["Single-Leg Romanian Deadlift",3,"8-10 each leg",60,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg, fast up",45,false],["Pallof Press",3,"8-10 each side",60,false],["Cable Wood Chopper",3,"8-10 each side",60,false]],"2":[["Neutral-Grip Dumbbell Bench Press",4,"3-5",180,false],["Chest-Supported Row",3,"5-6",120,false],["Incline Dumbbell Press",3,"5-6",120,false],["Band External Rotation",3,"10-12 each arm",45,false],["Dumbbell Rear-Delt Fly",3,"8-10",60,false],["Dumbbell Wrist Extension",3,"8-10",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Trap Bar Deadlift",4,"3-5",180,false],["Hip Thrust",3,"5-6",120,false],["Nordic Hamstring Curl",3,"6, slow on the way down",120,false],["Cable Hip Abduction",3,"8-10",60,false],["Back Extension",3,"8-10",60,false],["Dead Bug",3,"8-10 each side",60,false]],"5":[["Weighted Pull-Up",4,"3-5",180,false],["Dumbbell Single-Arm Row",3,"5-6 each arm",120,false],["Push-Up",3,"5-6",120,false],["Cable External Rotation",3,"10-12 each arm",45,false],["Band High Face Pull",3,"8-10",60,false],["Dumbbell Wrist Curl",3,"8-10",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Endurance – Baseball', 'For Baseball: a 12-week endurance program. Baseball is mostly standing with short bursts, but a strong aerobic base helps you recover between innings, between games and between pitches. The program builds that base, then adds short repeated efforts like a base-running day. Each week has 6 sessions: Monday zone 2 base, Tuesday intervals, Wednesday a short full-body strength session to keep your strength and protect your joints, Thursday tempo or threshold work, Friday easy recovery and mobility, and a long easy session on Saturday. Sunday is full rest. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds the aerobic base with short, light intervals. Block 2 (weeks 5-7) adds threshold work. Block 3 (weeks 9-11) adds harder, sport-specific intervals. The easy sessions get a little longer each block, and the interval rounds go up each week. Weeks 4 and 8 are recovery weeks with shorter easy sessions and half the intervals and strength sets. Week 12 is a test week: easy sessions, then a steady hard test on Tuesday so you can see how far you have come. Zone 2 means an easy pace where you can still chat. The hard efforts are about 8-9 out of 10 and the easy ones feel truly easy: most of your gains come from the easy days.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Endurance – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Endurance – Soccer'), '{"1":"Aerobic base: zone 2","2":"Intervals","3":"Strength maintenance (full body)","4":"Tempo and threshold","5":"Easy recovery + mobility","6":"Long session","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Steady State Ride",1,"30 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Running Intervals",6,"20 sec at 8/10, 70 sec easy jog between",90,true]],"3":[["Barbell Back Squat",2,"8-10",120,false],["Romanian Deadlift",2,"8-10",120,false],["Dumbbell Bulgarian Split Squat",2,"8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"40 sec",30,false]],"4":[["Treadmill Run",1,"20 min steady: comfortable pace, you can say a sentence",60,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Treadmill Run",1,"30 min easy: zone 2, a pace where you can talk",60,false]]},"p2":{"1":[["Steady State Ride",1,"35 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Running Intervals",6,"30 sec at 8/10, 90 sec easy jog between",90,true]],"3":[["Barbell Back Squat",2,"6-8",120,false],["Romanian Deadlift",2,"6-8",120,false],["Dumbbell Bulgarian Split Squat",2,"6-8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false]],"4":[["Tempo Run",2,"8 min at 7/10: comfortably hard, 3 min easy between",180,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Treadmill Run",1,"40 min easy: zone 2, a pace where you can talk",60,false]]},"p3":{"1":[["Steady State Ride",1,"40 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Running Intervals",6,"30 sec at 9/10, 90 sec easy jog between",90,true]],"3":[["Barbell Back Squat",2,"5-6",150,false],["Romanian Deadlift",2,"5-6",150,false],["Dumbbell Bulgarian Split Squat",2,"6 each leg",90,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false]],"4":[["Running Intervals",2,"6 x 30 m efforts at 9/10, walk back. 3 min between sets",180,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Treadmill Run",1,"45 min easy: zone 2, a pace where you can talk",60,false]]},"r1":{"1":[["Steady State Ride",1,"18 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Treadmill Run",1,"18 min easy: zone 2, a pace where you can talk",60,false]],"4":[["Treadmill Run",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r2":{"1":[["Steady State Ride",1,"21 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Treadmill Run",1,"24 min easy: zone 2, a pace where you can talk",60,false]],"4":[["Treadmill Run",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r3":{"1":[["Steady State Ride",1,"24 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Treadmill Run",1,"27 min easy: zone 2, a pace where you can talk",60,false]],"2":[["Running Intervals",1,"Test: 12 min at a steady hard pace. Note the distance you cover",60,false]],"4":[["Treadmill Run",1,"20 min easy: stay loose before your test",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Speed – Baseball', 'For Baseball: a 12-week speed program. Baseball speed is quick first steps for base running and fielding, plus rotational power for hitting and throwing. The program builds short sprint speed and fast hip rotation, with shoulder protection and no overhead pressing. Monday is acceleration and lower body strength, Tuesday upper body and trunk, Wednesday easy zone 2 and mobility, Thursday top speed and change of direction, and Friday power and elastic strength. Saturday is your sport or rest and Sunday is full rest. Hard sprinting never comes on back-to-back days. It runs in three 4-week blocks. Block 1 (weeks 1-3) learns good mechanics and builds a base at 8 out of 10 effort, so tendons and hamstrings are ready. Block 2 (weeks 5-7) goes all-out on acceleration and adds fast, springy work. Block 3 (weeks 9-11) peaks with the fastest efforts and the most reactive work. Weeks 4 and 8 are recovery weeks at half the sets, and week 12 is a test week at half the sets: test a 20 m sprint and a broad jump (or your best sprint on the bike) and compare with week 1. Rest fully between sprints: speed work is quality, not tiring conditioning, so stop the session if your form slips or a hamstring feels tight. No set goes to failure, and depth jumps are from a low box only.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Speed – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Speed – Soccer'), '{"3":"Active recovery: zone 2 + mobility","6":"Play your sport or rest","7":"Full rest","1":"Acceleration & lower body strength","2":"Upper body & trunk","4":"Top speed & change of direction","5":"Power & elastic strength"}'::jsonb, '{"p1":{"1":[["A-Skip",2,"20 m",60,false],["B-Skip",2,"20 m",60,false],["Wall Drive Drill",3,"3 x 5 sec, hold the lean and drive the knee",60,false],["Acceleration Sprint",5,"10-20 m at 8/10: smooth and fast, not all-out, walk back",90,true],["Barbell Back Squat",3,"5-6",150,true],["Hip Thrust",3,"8",90,false],["Nordic Hamstring Curl",2,"4-6, slow on the way down",120,true],["Single-Leg Standing Calf Raise",3,"12 each leg",45,false]],"2":[["Bench Press",3,"6-8",120,true],["Chest-Supported Row",3,"8",90,true],["Cable Seated Rope Face Pull",3,"12-15",45,false],["Band External Rotation",2,"12-15 each arm, light",45,false],["Medicine Ball Rotational Throw",3,"4 each side, fast",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Flying Sprint",3,"20 m build-up then 10 m at 90%",150,false],["Ladder Quick Feet",3,"1 pass, fast and light",60,false],["Pro Agility Shuttle",3,"1 at 8/10, learn the turns",120,false],["Pogo Hops",3,"10, stiff and quick",60,false]],"5":[["Jump Squat",3,"5, bodyweight, land softly",90,false],["Box Jump",3,"3, step down",90,false],["Medicine Ball Rotational Throw",3,"5 each side, fast",60,false],["Medicine Ball Scoop Toss",3,"5, hips drive it",60,false],["Hip Thrust",3,"8",90,false],["Pallof Press",3,"10 each side",45,false]]},"p2":{"1":[["A-Skip",2,"20 m",60,false],["Wall Drive Drill",2,"3 x 5 sec fast",60,false],["Acceleration Sprint",6,"10-20 m all-out, walk back and rest fully",120,true],["Barbell Back Squat",3,"3-5",180,true],["Hip Thrust",3,"6, fast up",90,false],["Nordic Hamstring Curl",3,"5-6, slow on the way down",120,false],["Single-Leg Standing Calf Raise",3,"10 each leg",45,false]],"2":[["Bench Press",3,"4-6",150,true],["Chest-Supported Row",3,"6-8",120,false],["Medicine Ball Chest Pass",3,"6, fast",60,false],["Cable Seated Rope Face Pull",3,"12",45,false],["Band External Rotation",2,"12-15 each arm, light",45,false],["Medicine Ball Rotational Throw",3,"4 each side, fast",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Flying Sprint",4,"20 m build-up then 20 m fast",180,false],["Pro Agility Shuttle",4,"1 all-out",120,false],["Crossover Run",3,"15 m each side",60,false],["Lateral Bound",3,"5 each side, stick it",60,false],["Single-Leg Hop",2,"5 each leg",60,false]],"5":[["Jump Squat",4,"4, light load, fast",90,false],["Box Jump",3,"3, step down",90,false],["Medicine Ball Rotational Throw",3,"5 each side, fast",60,false],["Medicine Ball Scoop Toss",3,"5, hips drive it",60,false],["Single-Leg Hop",2,"5 each leg",60,false],["Pallof Press",3,"10 each side",45,false]]},"p3":{"1":[["A-Skip",2,"20 m",60,false],["Falling Start Sprint",4,"10-20 m all-out, lean and fall into it",120,true],["Acceleration Sprint",4,"10-20 m all-out, full rest",120,false],["Barbell Back Squat",4,"3",180,false],["Hip Thrust",3,"5, fast up",90,false],["Nordic Hamstring Curl",3,"6, slow on the way down",120,false],["Single-Leg Standing Calf Raise",3,"8 each leg, fast up",45,false]],"2":[["Bench Press",4,"3-5",150,false],["Chest-Supported Row",3,"5-6",120,false],["Medicine Ball Chest Pass",3,"5, hard",60,false],["Cable Seated Rope Face Pull",3,"12",45,false],["Band External Rotation",2,"12-15 each arm, light",45,false],["Medicine Ball Rotational Throw",3,"4 each side, fast",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Flying Sprint",5,"20 m build-up then 20 m all-out",180,false],["Pro Agility Shuttle",4,"1 all-out",120,false],["Falling Start Sprint",3,"10 m all-out then stop under control",120,false],["Depth Jump",3,"4, from a low box (30-40 cm): step off, land and jump straight up",120,false],["Lateral Bound",3,"5 each side",60,false]],"5":[["Jump Squat",4,"3, light load, fast",90,false],["Broad Jump",3,"4, stick the landing",90,false],["Medicine Ball Rotational Throw",3,"5 each side, fast",60,false],["Bounding",3,"30 m",90,false],["Medicine Ball Scoop Toss",3,"4, hips drive it",60,false],["Single-Leg Hop",2,"5 each leg",60,false],["Pallof Press",3,"10 each side",45,false]]}}'::jsonb);
select public.add_sport_block('12-Week Strength – Basketball', 'For Basketball: a 12-week strength program. Basketball asks a lot of the knees and ankles: jumping, landing and stopping again and again. The program builds leg and hip strength for a higher jump and soft landings, with single-leg work, calf and shin strength for the ankles, and hamstring work for the knees. Four strength sessions a week (Monday lower body, Tuesday upper body, Thursday hips and hamstrings, Friday upper body and trunk) train every muscle twice a week, with an easy zone 2 and mobility session on Wednesday, your sport or rest on Saturday and a full rest on Sunday. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds muscle and tendon strength at 8-10 reps with sets going up each week. Block 2 (weeks 5-7) gets heavier at 4-6 reps. Block 3 (weeks 9-11) peaks strength at 3-5 reps with a few fast jumps or lifts on top. Weeks 4 and 8 are recovery weeks at half the sets so your body can absorb the work, and week 12 is a test week at half the sets: work up to your best clean set of 3-5 reps on the main lifts and stop when the bar slows or your form changes. No set goes to failure: stop each set with 1-2 good reps left, and add weight only when every rep is clean. There is no overhead pressing.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Strength – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Strength – Soccer'), '{"1":"Strength A: lower body","2":"Strength B: upper body","3":"Active recovery: zone 2 + mobility","4":"Strength C: hips & hamstrings","5":"Strength D: upper body & trunk","6":"Play your sport or rest","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Barbell Back Squat",3,"8-10",120,true],["Single-Leg Step-Down",3,"8-10 each leg",90,true],["Step-Up",3,"12-15 each leg",60,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Tibialis Raise",2,"15",45,false],["Pallof Press",3,"12-15 each side",60,false]],"2":[["Bench Press",3,"8-10",120,true],["Chest-Supported Row",3,"8-10",90,true],["Incline Dumbbell Press",3,"8-10",90,true],["Cable Seated Rope Face Pull",3,"12-15",60,false],["Hammer Curl",3,"12-15",60,false],["Cable Rope Pushdown",3,"12-15",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Trap Bar Deadlift",3,"8-10",120,true],["Hip Thrust",3,"8-10",90,true],["Nordic Hamstring Curl",2,"4-6, slow on the way down",120,true],["Cable Hip Abduction",3,"12-15",60,false],["Back Extension",3,"12-15",60,false],["Standing Calf Raise",3,"12-15",45,false],["Dead Bug",3,"12-15 each side",60,false]],"5":[["Pull-Up",3,"8-10",120,true],["Dumbbell Single-Arm Row",3,"8-10 each arm",90,true],["Neutral-Grip Dumbbell Bench Press",3,"8-10",90,true],["Dumbbell Rear-Delt Fly",3,"12-15",60,false],["Cable Wood Chopper",3,"12-15 each side",60,false],["Dumbbell Farmer''s Carry",2,"30 m",60,false]]},"p2":{"1":[["Barbell Back Squat",3,"4-6",180,true],["Single-Leg Step-Down",3,"6-8 each leg",120,false],["Step-Up",3,"10-12 each leg",60,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Tibialis Raise",2,"15-20",45,false],["Pallof Press",3,"10-12 each side",60,false]],"2":[["Bench Press",3,"4-6",180,true],["Chest-Supported Row",3,"6-8",120,false],["Incline Dumbbell Press",3,"6-8",120,false],["Cable Seated Rope Face Pull",3,"10-12",60,false],["Hammer Curl",3,"10-12",60,false],["Cable Rope Pushdown",3,"10-12",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Trap Bar Deadlift",3,"4-6",180,true],["Hip Thrust",3,"6-8",120,false],["Nordic Hamstring Curl",3,"5-6, slow on the way down",120,false],["Cable Hip Abduction",3,"10-12",60,false],["Back Extension",3,"10-12",60,false],["Standing Calf Raise",3,"10-12",45,false],["Dead Bug",3,"10-12 each side",60,false]],"5":[["Weighted Pull-Up",3,"4-6",180,true],["Dumbbell Single-Arm Row",3,"6-8 each arm",120,false],["Neutral-Grip Dumbbell Bench Press",3,"6-8",120,false],["Dumbbell Rear-Delt Fly",3,"10-12",60,false],["Cable Wood Chopper",3,"10-12 each side",60,false],["Dumbbell Farmer''s Carry",3,"30 m",60,false]]},"p3":{"1":[["Barbell Back Squat",4,"3-5",180,false],["Jump Squat",3,"3, light load, land softly and stick it",90,false],["Single-Leg Step-Down",3,"5-6 each leg",120,false],["Step-Up",3,"8-10 each leg",60,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg, fast up",45,false],["Tibialis Raise",2,"20",45,false],["Pallof Press",3,"8-10 each side",60,false]],"2":[["Bench Press",4,"3-5",180,false],["Chest-Supported Row",3,"5-6",120,false],["Incline Dumbbell Press",3,"5-6",120,false],["Cable Seated Rope Face Pull",3,"8-10",60,false],["Hammer Curl",3,"8-10",60,false],["Cable Rope Pushdown",3,"8-10",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Trap Bar Deadlift",4,"3-5",180,false],["Hip Thrust",3,"5-6",120,false],["Nordic Hamstring Curl",3,"6, slow on the way down",120,false],["Cable Hip Abduction",3,"8-10",60,false],["Back Extension",3,"8-10",60,false],["Standing Calf Raise",3,"8-10, fast up",45,false],["Dead Bug",3,"8-10 each side",60,false]],"5":[["Weighted Pull-Up",4,"3-5",180,false],["Dumbbell Single-Arm Row",3,"5-6 each arm",120,false],["Neutral-Grip Dumbbell Bench Press",3,"5-6",120,false],["Dumbbell Rear-Delt Fly",3,"8-10",60,false],["Cable Wood Chopper",3,"8-10 each side",60,false],["Dumbbell Farmer''s Carry",3,"40 m",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Endurance – Basketball', 'For Basketball: a 12-week endurance program. Basketball is non-stop running, jumping and stopping. The program builds an aerobic base, using the bike for some sessions to spare the knees and ankles, then adds the hard, short intervals that match a full court game. Each week has 6 sessions: Monday zone 2 base, Tuesday intervals, Wednesday a short full-body strength session to keep your strength and protect your joints, Thursday tempo or threshold work, Friday easy recovery and mobility, and a long easy session on Saturday. Sunday is full rest. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds the aerobic base with short, light intervals. Block 2 (weeks 5-7) adds threshold work. Block 3 (weeks 9-11) adds harder, sport-specific intervals. The easy sessions get a little longer each block, and the interval rounds go up each week. Weeks 4 and 8 are recovery weeks with shorter easy sessions and half the intervals and strength sets. Week 12 is a test week: easy sessions, then a steady hard test on Tuesday so you can see how far you have come. Zone 2 means an easy pace where you can still chat. The hard efforts are about 8-9 out of 10 and the easy ones feel truly easy: most of your gains come from the easy days.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Endurance – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Endurance – Soccer'), '{"1":"Aerobic base: zone 2","2":"Intervals","3":"Strength maintenance (full body)","4":"Tempo and threshold","5":"Easy recovery + mobility","6":"Long session","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Treadmill Run",1,"30 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Running Intervals",5,"1 min at 8/10, 2 min easy jog between",120,true]],"3":[["Barbell Back Squat",2,"8-10",120,false],["Romanian Deadlift",2,"8-10",120,false],["Dumbbell Bulgarian Split Squat",2,"8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"40 sec",30,false]],"4":[["Indoor Cycling Spin",1,"25 min steady on the bike: comfortable pace, easy on the knees",60,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Steady State Ride",1,"40 min easy: zone 2, a pace where you can talk",60,false]]},"p2":{"1":[["Treadmill Run",1,"35 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Running Intervals",3,"4 min at 8/10, 3 min easy jog between",180,true]],"3":[["Barbell Back Squat",2,"6-8",120,false],["Romanian Deadlift",2,"6-8",120,false],["Dumbbell Bulgarian Split Squat",2,"6-8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false]],"4":[["Cycling Intervals",2,"10 min at 7/10: comfortably hard, 3 min easy between",180,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Steady State Ride",1,"50 min easy: zone 2, a pace where you can talk",60,false]]},"p3":{"1":[["Treadmill Run",1,"40 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Running Intervals",4,"45 sec at 9/10, 45 sec easy between",120,true]],"3":[["Barbell Back Squat",2,"5-6",150,false],["Romanian Deadlift",2,"5-6",150,false],["Dumbbell Bulgarian Split Squat",2,"6 each leg",90,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false]],"4":[["Running Intervals",2,"6 x 30 m sprints with 20 sec between. 3 min between sets",180,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Steady State Ride",1,"60 min easy: zone 2, a pace where you can talk",60,false]]},"r1":{"1":[["Treadmill Run",1,"18 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Steady State Ride",1,"24 min easy: zone 2, a pace where you can talk",60,false]],"4":[["Indoor Cycling Spin",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r2":{"1":[["Treadmill Run",1,"21 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Steady State Ride",1,"30 min easy: zone 2, a pace where you can talk",60,false]],"4":[["Indoor Cycling Spin",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r3":{"1":[["Treadmill Run",1,"24 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Steady State Ride",1,"36 min easy: zone 2, a pace where you can talk",60,false]],"2":[["Running Intervals",1,"Test: 12 min at a steady hard pace. Note the distance you cover",60,false]],"4":[["Indoor Cycling Spin",1,"20 min easy: stay loose before your test",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Speed – Basketball', 'For Basketball: a 12-week speed program. Basketball speed is a quick first step, fast lateral movement and a higher jump. The program builds acceleration, defensive shuffling and jumping power, with soft landings that protect the knees and ankles. Monday is acceleration and lower body strength, Tuesday upper body and trunk, Wednesday easy zone 2 and mobility, Thursday top speed and change of direction, and Friday power and elastic strength. Saturday is your sport or rest and Sunday is full rest. Hard sprinting never comes on back-to-back days. It runs in three 4-week blocks. Block 1 (weeks 1-3) learns good mechanics and builds a base at 8 out of 10 effort, so tendons and hamstrings are ready. Block 2 (weeks 5-7) goes all-out on acceleration and adds fast, springy work. Block 3 (weeks 9-11) peaks with the fastest efforts and the most reactive work. Weeks 4 and 8 are recovery weeks at half the sets, and week 12 is a test week at half the sets: test a 20 m sprint and a broad jump (or your best sprint on the bike) and compare with week 1. Rest fully between sprints: speed work is quality, not tiring conditioning, so stop the session if your form slips or a hamstring feels tight. No set goes to failure, and depth jumps are from a low box only.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Speed – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Speed – Soccer'), '{"3":"Active recovery: zone 2 + mobility","6":"Play your sport or rest","7":"Full rest","1":"Acceleration & lower body strength","2":"Upper body & trunk","4":"Top speed & change of direction","5":"Power & elastic strength"}'::jsonb, '{"p1":{"1":[["A-Skip",2,"20 m",60,false],["B-Skip",2,"20 m",60,false],["Wall Drive Drill",3,"3 x 5 sec, hold the lean and drive the knee",60,false],["Acceleration Sprint",5,"10-15 m at 8/10: smooth and fast, not all-out, walk back",90,true],["Barbell Back Squat",3,"5-6",150,true],["Hip Thrust",3,"8",90,false],["Nordic Hamstring Curl",2,"4-6, slow on the way down",120,true],["Single-Leg Standing Calf Raise",3,"12 each leg",45,false]],"2":[["Bench Press",3,"6-8",120,true],["Chest-Supported Row",3,"8",90,true],["Cable Seated Rope Face Pull",3,"12-15",45,false],["Pallof Press",3,"10 each side",45,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Flying Sprint",3,"20 m build-up then 10 m at 90%",150,false],["Ladder Quick Feet",3,"1 pass, fast and light",60,false],["Pro Agility Shuttle",3,"1 at 8/10, learn the turns",120,false],["Lateral Shuffle",3,"10 m each way, low and quick",60,false],["Pogo Hops",3,"10, stiff and quick",60,false]],"5":[["Jump Squat",3,"5, bodyweight, land softly",90,false],["Box Jump",3,"3, step down",90,false],["Medicine Ball Slam",3,"8",60,false],["Medicine Ball Scoop Toss",3,"5, hips drive it",60,false],["Hip Thrust",3,"8",90,false],["Pallof Press",3,"10 each side",45,false]]},"p2":{"1":[["A-Skip",2,"20 m",60,false],["Wall Drive Drill",2,"3 x 5 sec fast",60,false],["Acceleration Sprint",6,"10-15 m all-out, walk back and rest fully",120,true],["Barbell Back Squat",3,"3-5",180,true],["Hip Thrust",3,"6, fast up",90,false],["Nordic Hamstring Curl",3,"5-6, slow on the way down",120,false],["Single-Leg Standing Calf Raise",3,"10 each leg",45,false]],"2":[["Bench Press",3,"4-6",150,true],["Chest-Supported Row",3,"6-8",120,false],["Medicine Ball Chest Pass",3,"6, fast",60,false],["Cable Seated Rope Face Pull",3,"12",45,false],["Pallof Press",3,"10 each side",45,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Flying Sprint",4,"20 m build-up then 20 m fast",180,false],["Backpedal",3,"15 m then turn and sprint",60,false],["Pro Agility Shuttle",4,"1 all-out",120,false],["Lateral Bound",3,"5 each side, stick it",60,false],["Lateral Shuffle",3,"10 m each way, low and quick",60,false],["Single-Leg Hop",2,"5 each leg",60,false]],"5":[["Jump Squat",4,"4, light load, fast",90,false],["Box Jump",3,"3, step down",90,false],["Medicine Ball Slam",3,"6, hard",60,false],["Medicine Ball Scoop Toss",3,"5, hips drive it",60,false],["Single-Leg Hop",2,"5 each leg",60,false],["Pallof Press",3,"10 each side",45,false]]},"p3":{"1":[["A-Skip",2,"20 m",60,false],["Falling Start Sprint",4,"10-15 m all-out, lean and fall into it",120,true],["Acceleration Sprint",4,"10-15 m all-out, full rest",120,false],["Barbell Back Squat",4,"3",180,false],["Hip Thrust",3,"5, fast up",90,false],["Nordic Hamstring Curl",3,"6, slow on the way down",120,false],["Single-Leg Standing Calf Raise",3,"8 each leg, fast up",45,false]],"2":[["Bench Press",4,"3-5",150,false],["Chest-Supported Row",3,"5-6",120,false],["Medicine Ball Chest Pass",3,"5, hard",60,false],["Cable Seated Rope Face Pull",3,"12",45,false],["Pallof Press",3,"10 each side",45,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Flying Sprint",5,"20 m build-up then 20 m all-out",180,false],["Pro Agility Shuttle",4,"1 all-out",120,false],["Falling Start Sprint",3,"10 m all-out then stop under control",120,false],["Depth Jump",3,"4, from a low box (30-40 cm): step off, land and jump straight up",120,false],["Lateral Shuffle",3,"10 m each way, low and quick",60,false],["Lateral Bound",3,"5 each side",60,false]],"5":[["Jump Squat",4,"3, light load, fast",90,false],["Broad Jump",3,"4, stick the landing",90,false],["Bounding",3,"30 m",90,false],["Medicine Ball Scoop Toss",3,"4, hips drive it",60,false],["Single-Leg Hop",2,"5 each leg",60,false],["Pallof Press",3,"10 each side",45,false]]}}'::jsonb);
select public.add_sport_block('12-Week Strength – Tennis', 'For Tennis: a 12-week strength program. Tennis is played sideways, on one leg and with a twist. The program builds strong legs and hips for lateral movement, trunk rotation for serves and groundstrokes, and shoulders, elbows and wrists that last. There is no overhead pressing: the rotator cuff, upper back and forearms get the work instead. Four strength sessions a week (Monday lower body, Tuesday upper body, Thursday hips and hamstrings, Friday upper body and trunk) train every muscle twice a week, with an easy zone 2 and mobility session on Wednesday, your sport or rest on Saturday and a full rest on Sunday. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds muscle and tendon strength at 8-10 reps with sets going up each week. Block 2 (weeks 5-7) gets heavier at 4-6 reps. Block 3 (weeks 9-11) peaks strength at 3-5 reps with a few fast jumps or lifts on top. Weeks 4 and 8 are recovery weeks at half the sets so your body can absorb the work, and week 12 is a test week at half the sets: work up to your best clean set of 3-5 reps on the main lifts and stop when the bar slows or your form changes. No set goes to failure: stop each set with 1-2 good reps left, and add weight only when every rep is clean. There is no overhead pressing.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Strength – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Strength – Soccer'), '{"1":"Strength A: lower body","2":"Strength B: upper body","3":"Active recovery: zone 2 + mobility","4":"Strength C: hips & hamstrings","5":"Strength D: upper body & trunk","6":"Play your sport or rest","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Barbell Back Squat",3,"8-10",120,true],["Dumbbell Lateral Lunge",3,"8-10 each side",90,true],["Cossack Squat",3,"12-15 each side",60,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Pallof Press",3,"12-15 each side",60,false],["Cable Wood Chopper",3,"12-15 each side",60,false]],"2":[["Neutral-Grip Dumbbell Bench Press",3,"8-10",120,true],["Chest-Supported Row",3,"8-10",90,true],["Incline Dumbbell Press",3,"8-10",90,true],["Band External Rotation",2,"12-15 each arm, light",45,false],["Dumbbell Rear-Delt Fly",3,"12-15",60,false],["Dumbbell Wrist Extension",3,"12-15",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Trap Bar Deadlift",3,"8-10",120,true],["Hip Thrust",3,"8-10",90,true],["Nordic Hamstring Curl",2,"4-6, slow on the way down",120,true],["Cable Hip Abduction",3,"12-15",60,false],["Back Extension",3,"12-15",60,false],["Dead Bug",3,"12-15 each side",60,false]],"5":[["Pull-Up",3,"8-10",120,true],["Dumbbell Single-Arm Row",3,"8-10 each arm",90,true],["Push-Up",3,"8-10",90,true],["Cable External Rotation",2,"12-15 each arm, light",45,false],["Band High Face Pull",3,"12-15",60,false],["Dumbbell Wrist Curl",3,"12-15",60,false]]},"p2":{"1":[["Barbell Back Squat",3,"4-6",180,true],["Dumbbell Lateral Lunge",3,"6-8 each side",120,false],["Cossack Squat",3,"10-12 each side",60,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Pallof Press",3,"10-12 each side",60,false],["Cable Wood Chopper",3,"10-12 each side",60,false]],"2":[["Neutral-Grip Dumbbell Bench Press",3,"4-6",180,true],["Chest-Supported Row",3,"6-8",120,false],["Incline Dumbbell Press",3,"6-8",120,false],["Band External Rotation",3,"12 each arm",45,false],["Dumbbell Rear-Delt Fly",3,"10-12",60,false],["Dumbbell Wrist Extension",3,"10-12",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Trap Bar Deadlift",3,"4-6",180,true],["Hip Thrust",3,"6-8",120,false],["Nordic Hamstring Curl",3,"5-6, slow on the way down",120,false],["Cable Hip Abduction",3,"10-12",60,false],["Back Extension",3,"10-12",60,false],["Dead Bug",3,"10-12 each side",60,false]],"5":[["Weighted Pull-Up",3,"4-6",180,true],["Dumbbell Single-Arm Row",3,"6-8 each arm",120,false],["Push-Up",3,"6-8",120,false],["Cable External Rotation",3,"12 each arm",45,false],["Band High Face Pull",3,"10-12",60,false],["Dumbbell Wrist Curl",3,"10-12",60,false]]},"p3":{"1":[["Barbell Back Squat",4,"3-5",180,false],["Medicine Ball Rotational Throw",3,"4 each side, fast",60,false],["Dumbbell Lateral Lunge",3,"5-6 each side",120,false],["Cossack Squat",3,"8-10 each side",60,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg, fast up",45,false],["Pallof Press",3,"8-10 each side",60,false],["Cable Wood Chopper",3,"8-10 each side",60,false]],"2":[["Neutral-Grip Dumbbell Bench Press",4,"3-5",180,false],["Chest-Supported Row",3,"5-6",120,false],["Incline Dumbbell Press",3,"5-6",120,false],["Band External Rotation",3,"10-12 each arm",45,false],["Dumbbell Rear-Delt Fly",3,"8-10",60,false],["Dumbbell Wrist Extension",3,"8-10",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Trap Bar Deadlift",4,"3-5",180,false],["Hip Thrust",3,"5-6",120,false],["Nordic Hamstring Curl",3,"6, slow on the way down",120,false],["Cable Hip Abduction",3,"8-10",60,false],["Back Extension",3,"8-10",60,false],["Dead Bug",3,"8-10 each side",60,false]],"5":[["Weighted Pull-Up",4,"3-5",180,false],["Dumbbell Single-Arm Row",3,"5-6 each arm",120,false],["Push-Up",3,"5-6",120,false],["Cable External Rotation",3,"10-12 each arm",45,false],["Band High Face Pull",3,"8-10",60,false],["Dumbbell Wrist Curl",3,"8-10",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Endurance – Tennis', 'For Tennis: a 12-week endurance program. A tennis match can last hours, with short rallies and short rests. The program builds an aerobic base so you recover between points and still move well in the third set, then adds the rally-length intervals you need. Each week has 6 sessions: Monday zone 2 base, Tuesday intervals, Wednesday a short full-body strength session to keep your strength and protect your joints, Thursday tempo or threshold work, Friday easy recovery and mobility, and a long easy session on Saturday. Sunday is full rest. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds the aerobic base with short, light intervals. Block 2 (weeks 5-7) adds threshold work. Block 3 (weeks 9-11) adds harder, sport-specific intervals. The easy sessions get a little longer each block, and the interval rounds go up each week. Weeks 4 and 8 are recovery weeks with shorter easy sessions and half the intervals and strength sets. Week 12 is a test week: easy sessions, then a steady hard test on Tuesday so you can see how far you have come. Zone 2 means an easy pace where you can still chat. The hard efforts are about 8-9 out of 10 and the easy ones feel truly easy: most of your gains come from the easy days.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Endurance – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Endurance – Soccer'), '{"1":"Aerobic base: zone 2","2":"Intervals","3":"Strength maintenance (full body)","4":"Tempo and threshold","5":"Easy recovery + mobility","6":"Long session","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Treadmill Run",1,"30 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Running Intervals",6,"30 sec at 8/10, 30 sec easy between",120,true]],"3":[["Barbell Back Squat",2,"8-10",120,false],["Romanian Deadlift",2,"8-10",120,false],["Dumbbell Bulgarian Split Squat",2,"8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"40 sec",30,false]],"4":[["Steady State Ride",1,"25 min steady: comfortable pace, you can say a sentence",60,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Treadmill Run",1,"40 min easy: zone 2, a pace where you can talk",60,false]]},"p2":{"1":[["Treadmill Run",1,"35 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Running Intervals",3,"4 min at 8/10, 3 min easy jog between",180,true]],"3":[["Barbell Back Squat",2,"6-8",120,false],["Romanian Deadlift",2,"6-8",120,false],["Dumbbell Bulgarian Split Squat",2,"6-8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false]],"4":[["Tempo Run",2,"10 min at 7/10: comfortably hard, 3 min easy between",180,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Treadmill Run",1,"50 min easy: zone 2, a pace where you can talk",60,false]]},"p3":{"1":[["Treadmill Run",1,"40 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Running Intervals",4,"45 sec at 9/10, 45 sec easy between",120,true]],"3":[["Barbell Back Squat",2,"5-6",150,false],["Romanian Deadlift",2,"5-6",150,false],["Dumbbell Bulgarian Split Squat",2,"6 each leg",90,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false]],"4":[["Running Intervals",2,"6 x 15 m sprints with 20 sec between. 3 min between sets",180,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Treadmill Run",1,"60 min easy: zone 2, a pace where you can talk",60,false]]},"r1":{"1":[["Treadmill Run",1,"18 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Treadmill Run",1,"24 min easy: zone 2, a pace where you can talk",60,false]],"4":[["Steady State Ride",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r2":{"1":[["Treadmill Run",1,"21 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Treadmill Run",1,"30 min easy: zone 2, a pace where you can talk",60,false]],"4":[["Steady State Ride",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r3":{"1":[["Treadmill Run",1,"24 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Treadmill Run",1,"36 min easy: zone 2, a pace where you can talk",60,false]],"2":[["Running Intervals",1,"Test: 12 min at a steady hard pace. Note the distance you cover",60,false]],"4":[["Steady State Ride",1,"20 min easy: stay loose before your test",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Speed – Tennis', 'For Tennis: a 12-week speed program. Tennis speed is the first two or three steps, fast lateral movement and quick recovery to the middle. The program builds short sprints, side-to-side speed and rotational power, with shoulder protection and no overhead pressing. Monday is acceleration and lower body strength, Tuesday upper body and trunk, Wednesday easy zone 2 and mobility, Thursday top speed and change of direction, and Friday power and elastic strength. Saturday is your sport or rest and Sunday is full rest. Hard sprinting never comes on back-to-back days. It runs in three 4-week blocks. Block 1 (weeks 1-3) learns good mechanics and builds a base at 8 out of 10 effort, so tendons and hamstrings are ready. Block 2 (weeks 5-7) goes all-out on acceleration and adds fast, springy work. Block 3 (weeks 9-11) peaks with the fastest efforts and the most reactive work. Weeks 4 and 8 are recovery weeks at half the sets, and week 12 is a test week at half the sets: test a 20 m sprint and a broad jump (or your best sprint on the bike) and compare with week 1. Rest fully between sprints: speed work is quality, not tiring conditioning, so stop the session if your form slips or a hamstring feels tight. No set goes to failure, and depth jumps are from a low box only.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Speed – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Speed – Soccer'), '{"3":"Active recovery: zone 2 + mobility","6":"Play your sport or rest","7":"Full rest","1":"Acceleration & lower body strength","2":"Upper body & trunk","4":"Top speed & change of direction","5":"Power & elastic strength"}'::jsonb, '{"p1":{"1":[["A-Skip",2,"20 m",60,false],["B-Skip",2,"20 m",60,false],["Wall Drive Drill",3,"3 x 5 sec, hold the lean and drive the knee",60,false],["Acceleration Sprint",5,"5-10 m at 8/10: smooth and fast, not all-out, walk back",90,true],["Barbell Back Squat",3,"5-6",150,true],["Hip Thrust",3,"8",90,false],["Nordic Hamstring Curl",2,"4-6, slow on the way down",120,true],["Single-Leg Standing Calf Raise",3,"12 each leg",45,false]],"2":[["Bench Press",3,"6-8",120,true],["Chest-Supported Row",3,"8",90,true],["Cable Seated Rope Face Pull",3,"12-15",45,false],["Band External Rotation",2,"12-15 each arm, light",45,false],["Medicine Ball Rotational Throw",3,"4 each side, fast",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Flying Sprint",3,"20 m build-up then 10 m at 90%",150,false],["Ladder Quick Feet",3,"1 pass, fast and light",60,false],["Pro Agility Shuttle",3,"1 at 8/10, learn the turns",120,false],["Lateral Shuffle",3,"10 m each way, low and quick",60,false],["Pogo Hops",3,"10, stiff and quick",60,false]],"5":[["Jump Squat",3,"5, bodyweight, land softly",90,false],["Box Jump",3,"3, step down",90,false],["Medicine Ball Rotational Throw",3,"5 each side, fast",60,false],["Medicine Ball Scoop Toss",3,"5, hips drive it",60,false],["Hip Thrust",3,"8",90,false],["Pallof Press",3,"10 each side",45,false]]},"p2":{"1":[["A-Skip",2,"20 m",60,false],["Wall Drive Drill",2,"3 x 5 sec fast",60,false],["Acceleration Sprint",6,"5-10 m all-out, walk back and rest fully",120,true],["Barbell Back Squat",3,"3-5",180,true],["Hip Thrust",3,"6, fast up",90,false],["Nordic Hamstring Curl",3,"5-6, slow on the way down",120,false],["Single-Leg Standing Calf Raise",3,"10 each leg",45,false]],"2":[["Bench Press",3,"4-6",150,true],["Chest-Supported Row",3,"6-8",120,false],["Medicine Ball Chest Pass",3,"6, fast",60,false],["Cable Seated Rope Face Pull",3,"12",45,false],["Band External Rotation",2,"12-15 each arm, light",45,false],["Medicine Ball Rotational Throw",3,"4 each side, fast",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Flying Sprint",4,"20 m build-up then 20 m fast",180,false],["Pro Agility Shuttle",4,"1 all-out",120,false],["Crossover Run",3,"15 m each side",60,false],["Lateral Bound",3,"5 each side, stick it",60,false],["Lateral Shuffle",3,"10 m each way, low and quick",60,false],["Single-Leg Hop",2,"5 each leg",60,false]],"5":[["Jump Squat",4,"4, light load, fast",90,false],["Box Jump",3,"3, step down",90,false],["Medicine Ball Rotational Throw",3,"5 each side, fast",60,false],["Medicine Ball Scoop Toss",3,"5, hips drive it",60,false],["Single-Leg Hop",2,"5 each leg",60,false],["Pallof Press",3,"10 each side",45,false]]},"p3":{"1":[["A-Skip",2,"20 m",60,false],["Falling Start Sprint",4,"5-10 m all-out, lean and fall into it",120,true],["Acceleration Sprint",4,"5-10 m all-out, full rest",120,false],["Barbell Back Squat",4,"3",180,false],["Hip Thrust",3,"5, fast up",90,false],["Nordic Hamstring Curl",3,"6, slow on the way down",120,false],["Single-Leg Standing Calf Raise",3,"8 each leg, fast up",45,false]],"2":[["Bench Press",4,"3-5",150,false],["Chest-Supported Row",3,"5-6",120,false],["Medicine Ball Chest Pass",3,"5, hard",60,false],["Cable Seated Rope Face Pull",3,"12",45,false],["Band External Rotation",2,"12-15 each arm, light",45,false],["Medicine Ball Rotational Throw",3,"4 each side, fast",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Flying Sprint",5,"20 m build-up then 20 m all-out",180,false],["Pro Agility Shuttle",4,"1 all-out",120,false],["Falling Start Sprint",3,"10 m all-out then stop under control",120,false],["Depth Jump",3,"4, from a low box (30-40 cm): step off, land and jump straight up",120,false],["Lateral Shuffle",3,"10 m each way, low and quick",60,false],["Lateral Bound",3,"5 each side",60,false]],"5":[["Jump Squat",4,"3, light load, fast",90,false],["Broad Jump",3,"4, stick the landing",90,false],["Medicine Ball Rotational Throw",3,"5 each side, fast",60,false],["Bounding",3,"30 m",90,false],["Medicine Ball Scoop Toss",3,"4, hips drive it",60,false],["Single-Leg Hop",2,"5 each leg",60,false],["Pallof Press",3,"10 each side",45,false]]}}'::jsonb);
select public.add_sport_block('12-Week Strength – Enduro Riding', 'For Enduro Riding: a 12-week strength program. Enduro riding is hours of standing on the pegs, absorbing bumps and fighting the bike. The program builds strong legs and hips for the standing position, a strong back, core and neck, and grip and forearms that fight arm pump. Four strength sessions a week (Monday lower body, Tuesday upper body, Thursday hips and hamstrings, Friday upper body and trunk) train every muscle twice a week, with an easy zone 2 and mobility session on Wednesday, your sport or rest on Saturday and a full rest on Sunday. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds muscle and tendon strength at 8-10 reps with sets going up each week. Block 2 (weeks 5-7) gets heavier at 4-6 reps. Block 3 (weeks 9-11) peaks strength at 3-5 reps with a few fast jumps or lifts on top. Weeks 4 and 8 are recovery weeks at half the sets so your body can absorb the work, and week 12 is a test week at half the sets: work up to your best clean set of 3-5 reps on the main lifts and stop when the bar slows or your form changes. No set goes to failure: stop each set with 1-2 good reps left, and add weight only when every rep is clean. There is no overhead pressing.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Strength – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Strength – Soccer'), '{"1":"Strength A: legs","2":"Strength B: upper body","3":"Easy spin + mobility","4":"Strength C: hips & hamstrings","5":"Strength D: back, trunk & grip","6":"Ride or rest","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Barbell Back Squat",3,"8-10",120,true],["Dumbbell Bulgarian Split Squat",3,"8-10 each leg",90,true],["Walking Lunge",3,"12-15 each leg",60,false],["Wall Sit",3,"45 sec",60,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Pallof Press",3,"12-15 each side",60,false]],"2":[["Bench Press",3,"8-10",120,true],["Chest-Supported Row",3,"8-10",90,true],["Incline Dumbbell Press",3,"8-10",90,true],["Cable Seated Rope Face Pull",3,"12-15",60,false],["Neck Curl",2,"15-20, light and slow",45,false],["Neck Extension",2,"15-20, light and slow",45,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Romanian Deadlift",3,"8-10",120,true],["Hip Thrust",3,"8-10",90,true],["Seated Leg Curl",3,"12-15",60,false],["Back Extension",3,"12-15",60,false],["Dumbbell Farmer''s Carry",2,"30 m",60,false],["Dead Bug",3,"12-15 each side",60,false]],"5":[["Pull-Up",3,"8-10",120,true],["Dumbbell Single-Arm Row",3,"8-10 each arm",90,true],["Neutral-Grip Dumbbell Bench Press",3,"8-10",90,true],["Dead Hang",2,"20-30 sec",60,false],["Dumbbell Wrist Curl",3,"12-15",60,false],["Plank",3,"12-15",60,false]]},"p2":{"1":[["Barbell Back Squat",3,"4-6",180,true],["Dumbbell Bulgarian Split Squat",3,"6-8 each leg",120,false],["Walking Lunge",3,"10-12 each leg",60,false],["Wall Sit",3,"60 sec",60,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Pallof Press",3,"10-12 each side",60,false]],"2":[["Bench Press",3,"4-6",180,true],["Chest-Supported Row",3,"6-8",120,false],["Incline Dumbbell Press",3,"6-8",120,false],["Cable Seated Rope Face Pull",3,"10-12",60,false],["Neck Curl",2,"15-20, light and slow",45,false],["Neck Extension",2,"15-20, light and slow",45,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Romanian Deadlift",3,"4-6",180,true],["Hip Thrust",3,"6-8",120,false],["Seated Leg Curl",3,"10-12",60,false],["Back Extension",3,"10-12",60,false],["Dumbbell Farmer''s Carry",3,"30 m",60,false],["Dead Bug",3,"10-12 each side",60,false]],"5":[["Weighted Pull-Up",3,"4-6",180,true],["Dumbbell Single-Arm Row",3,"6-8 each arm",120,false],["Neutral-Grip Dumbbell Bench Press",3,"6-8",120,false],["Dead Hang",2,"30-40 sec",60,false],["Dumbbell Wrist Curl",3,"10-12",60,false],["Plank",3,"10-12",60,false]]},"p3":{"1":[["Barbell Back Squat",4,"3-5",180,false],["Jump Squat",3,"3, light load, land softly",90,false],["Dumbbell Bulgarian Split Squat",3,"5-6 each leg",120,false],["Walking Lunge",3,"8-10 each leg",60,false],["Wall Sit",3,"75 sec",60,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg, fast up",45,false],["Pallof Press",3,"8-10 each side",60,false]],"2":[["Bench Press",4,"3-5",180,false],["Chest-Supported Row",3,"5-6",120,false],["Incline Dumbbell Press",3,"5-6",120,false],["Cable Seated Rope Face Pull",3,"8-10",60,false],["Neck Curl",2,"15-20, light and slow",45,false],["Neck Extension",2,"15-20, light and slow",45,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Romanian Deadlift",4,"3-5",180,false],["Hip Thrust",3,"5-6",120,false],["Seated Leg Curl",3,"8-10",60,false],["Back Extension",3,"8-10",60,false],["Dumbbell Farmer''s Carry",3,"40 m",60,false],["Dead Bug",3,"8-10 each side",60,false]],"5":[["Weighted Pull-Up",4,"3-5",180,false],["Dumbbell Single-Arm Row",3,"5-6 each arm",120,false],["Neutral-Grip Dumbbell Bench Press",3,"5-6",120,false],["Dead Hang",2,"30-45 sec, stop before your grip gives",60,false],["Dumbbell Wrist Curl",3,"8-10",60,false],["Plank",3,"8-10",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Endurance – Enduro Riding', 'For Enduro Riding: a 12-week endurance program. Enduro is hours of riding with a heart rate that stays high and forearms that burn. The program builds a big aerobic base and the ability to keep working hard, with the SkiErg and rower for the upper body and a long ride on Saturday. Each week has 6 sessions: Monday zone 2 base, Tuesday intervals, Wednesday a short full-body strength session to keep your strength and protect your joints, Thursday tempo or threshold work, Friday easy recovery and mobility, and a long easy session on Saturday. Sunday is full rest. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds the aerobic base with short, light intervals. Block 2 (weeks 5-7) adds threshold work. Block 3 (weeks 9-11) adds harder, sport-specific intervals. The easy sessions get a little longer each block, and the interval rounds go up each week. Weeks 4 and 8 are recovery weeks with shorter easy sessions and half the intervals and strength sets. Week 12 is a test week: easy sessions, then a steady hard test on Tuesday so you can see how far you have come. Zone 2 means an easy pace where you can still chat. The hard efforts are about 8-9 out of 10 and the easy ones feel truly easy: most of your gains come from the easy days.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Endurance – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Endurance – Soccer'), '{"1":"Aerobic base: zone 2","2":"Intervals","3":"Strength maintenance (full body)","4":"Tempo and threshold","5":"Easy recovery + mobility","6":"Long session","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Rowing Machine Steady State",1,"30 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Rowing Intervals",5,"1 min at 8/10, 2 min easy between",120,true]],"3":[["Barbell Back Squat",2,"8-10",120,false],["Romanian Deadlift",2,"8-10",120,false],["Dumbbell Bulgarian Split Squat",2,"8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"40 sec",30,false],["Dumbbell Farmer''s Carry",2,"30 m",60,false]],"4":[["SkiErg",1,"20 min steady: comfortable pace, you can say a sentence",60,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Steady State Ride",1,"45 min easy: zone 2, a pace where you can talk",60,false]]},"p2":{"1":[["Rowing Machine Steady State",1,"35 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Rowing Intervals",3,"4 min at 8/10, 3 min easy between",180,true]],"3":[["Barbell Back Squat",2,"6-8",120,false],["Romanian Deadlift",2,"6-8",120,false],["Dumbbell Bulgarian Split Squat",2,"6-8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false],["Dumbbell Farmer''s Carry",2,"30 m",60,false]],"4":[["SkiErg",2,"8 min at 7/10: comfortably hard, 3 min easy between",180,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Steady State Ride",1,"60 min easy: zone 2, a pace where you can talk",60,false]]},"p3":{"1":[["Rowing Machine Steady State",1,"40 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Rowing Intervals",4,"4 min at 9/10, 3 min easy between",180,false]],"3":[["Barbell Back Squat",2,"5-6",150,false],["Romanian Deadlift",2,"5-6",150,false],["Dumbbell Bulgarian Split Squat",2,"6 each leg",90,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false],["Dumbbell Farmer''s Carry",2,"30 m",60,false]],"4":[["Assault Bike",6,"30 sec hard at 8/10, 90 sec easy between",90,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Steady State Ride",1,"75 min easy: zone 2, a pace where you can talk",60,false]]},"r1":{"1":[["Rowing Machine Steady State",1,"18 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Steady State Ride",1,"27 min easy: zone 2, a pace where you can talk",60,false]],"4":[["SkiErg",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r2":{"1":[["Rowing Machine Steady State",1,"21 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Steady State Ride",1,"36 min easy: zone 2, a pace where you can talk",60,false]],"4":[["SkiErg",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r3":{"1":[["Rowing Machine Steady State",1,"24 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Steady State Ride",1,"45 min easy: zone 2, a pace where you can talk",60,false]],"2":[["Rowing Intervals",1,"Test: 2000 m at a steady hard pace. Note your time",60,false]],"4":[["SkiErg",1,"20 min easy: stay loose before your test",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Speed – Enduro Riding', 'For Enduro Riding: a 12-week speed program. Enduro speed means quick reactions and explosive power: standing up fast, absorbing a hit and getting back on the gas. The program builds explosive hips and legs, quick feet and fast hands, and a trunk that stays solid. Monday is acceleration and lower body strength, Tuesday upper body and trunk, Wednesday easy zone 2 and mobility, Thursday top speed and change of direction, and Friday power and elastic strength. Saturday is your sport or rest and Sunday is full rest. Hard sprinting never comes on back-to-back days. It runs in three 4-week blocks. Block 1 (weeks 1-3) learns good mechanics and builds a base at 8 out of 10 effort, so tendons and hamstrings are ready. Block 2 (weeks 5-7) goes all-out on acceleration and adds fast, springy work. Block 3 (weeks 9-11) peaks with the fastest efforts and the most reactive work. Weeks 4 and 8 are recovery weeks at half the sets, and week 12 is a test week at half the sets: test a 20 m sprint and a broad jump (or your best sprint on the bike) and compare with week 1. Rest fully between sprints: speed work is quality, not tiring conditioning, so stop the session if your form slips or a hamstring feels tight. No set goes to failure, and depth jumps are from a low box only.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Speed – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Speed – Soccer'), '{"3":"Active recovery: zone 2 + mobility","6":"Play your sport or rest","7":"Full rest","1":"Acceleration & lower body strength","2":"Upper body & trunk","4":"Top speed & change of direction","5":"Power & elastic strength"}'::jsonb, '{"p1":{"1":[["A-Skip",2,"20 m",60,false],["B-Skip",2,"20 m",60,false],["Wall Drive Drill",3,"3 x 5 sec, hold the lean and drive the knee",60,false],["Acceleration Sprint",5,"10-15 m at 8/10: smooth and fast, not all-out, walk back",90,true],["Ladder Quick Feet",3,"1 pass, fast and light",60,false],["Barbell Back Squat",3,"5-6",150,true],["Hip Thrust",3,"8",90,false],["Single-Leg Standing Calf Raise",3,"12 each leg",45,false],["Seated Leg Curl",3,"10",60,false]],"2":[["Bench Press",3,"6-8",120,true],["Chest-Supported Row",3,"8",90,true],["Cable Seated Rope Face Pull",3,"12-15",45,false],["Pull-Up",3,"6-8",90,false],["Plank",2,"40 sec",30,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Ladder Quick Feet",3,"1 pass, fast and light",60,false],["Pogo Hops",3,"10, stiff and quick",60,false],["Battle Ropes",4,"20 sec fast waves, 40 sec rest",60,false]],"5":[["Kettlebell Swing",4,"8, hips snap",90,false],["Jump Squat",3,"5, bodyweight, land softly",90,false],["Box Jump",3,"3, step down",90,false],["Medicine Ball Slam",3,"8",60,false],["Medicine Ball Scoop Toss",3,"5, hips drive it",60,false],["Hip Thrust",3,"8",90,false],["Pallof Press",3,"10 each side",45,false]]},"p2":{"1":[["A-Skip",2,"20 m",60,false],["Wall Drive Drill",2,"3 x 5 sec fast",60,false],["Acceleration Sprint",6,"10-15 m all-out, walk back and rest fully",120,true],["Ladder Quick Feet",3,"1 pass, fast and light",60,false],["Barbell Back Squat",3,"3-5",180,true],["Hip Thrust",3,"6, fast up",90,false],["Single-Leg Standing Calf Raise",3,"10 each leg",45,false],["Seated Leg Curl",3,"10",60,false]],"2":[["Bench Press",3,"4-6",150,true],["Chest-Supported Row",3,"6-8",120,false],["Medicine Ball Chest Pass",3,"6, fast",60,false],["Cable Seated Rope Face Pull",3,"12",45,false],["Pull-Up",3,"6-8",90,false],["Plank",2,"40 sec",30,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Lateral Bound",3,"5 each side, stick it",60,false],["Single-Leg Hop",2,"5 each leg",60,false],["Battle Ropes",4,"20 sec fast waves, 40 sec rest",60,false]],"5":[["Kettlebell Swing",4,"8, hips snap",90,false],["Jump Squat",4,"4, light load, fast",90,false],["Box Jump",3,"3, step down",90,false],["Medicine Ball Slam",3,"6, hard",60,false],["Medicine Ball Scoop Toss",3,"5, hips drive it",60,false],["Single-Leg Hop",2,"5 each leg",60,false],["Pallof Press",3,"10 each side",45,false]]},"p3":{"1":[["A-Skip",2,"20 m",60,false],["Falling Start Sprint",4,"10-15 m all-out, lean and fall into it",120,true],["Acceleration Sprint",4,"10-15 m all-out, full rest",120,false],["Ladder Quick Feet",3,"1 pass, fast and light",60,false],["Barbell Back Squat",4,"3",180,false],["Hip Thrust",3,"5, fast up",90,false],["Single-Leg Standing Calf Raise",3,"8 each leg, fast up",45,false],["Seated Leg Curl",3,"10",60,false]],"2":[["Bench Press",4,"3-5",150,false],["Chest-Supported Row",3,"5-6",120,false],["Medicine Ball Chest Pass",3,"5, hard",60,false],["Cable Seated Rope Face Pull",3,"12",45,false],["Pull-Up",3,"6-8",90,false],["Plank",2,"40 sec",30,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["A-Skip",2,"20 m",60,false],["Falling Start Sprint",3,"10 m all-out then stop under control",120,false],["Lateral Bound",3,"5 each side",60,false],["Battle Ropes",4,"20 sec fast waves, 40 sec rest",60,false]],"5":[["Kettlebell Swing",4,"8, hips snap",90,false],["Jump Squat",4,"3, light load, fast",90,false],["Medicine Ball Scoop Toss",3,"4, hips drive it",60,false],["Single-Leg Hop",2,"5 each leg",60,false],["Pallof Press",3,"10 each side",45,false]]}}'::jsonb);
select public.add_sport_block('12-Week Strength – Cycling', 'For Cycling: a 12-week strength program. Cycling power comes from the legs and hips, but a strong back and core let you hold the position and push harder for hours. The program builds leg and hip strength for more power on the pedals, and back, core and upper body strength that keep you comfortable and strong on the bike. Four strength sessions a week (Monday lower body, Tuesday upper body, Thursday hips and hamstrings, Friday upper body and trunk) train every muscle twice a week, with an easy zone 2 and mobility session on Wednesday, your sport or rest on Saturday and a full rest on Sunday. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds muscle and tendon strength at 8-10 reps with sets going up each week. Block 2 (weeks 5-7) gets heavier at 4-6 reps. Block 3 (weeks 9-11) peaks strength at 3-5 reps with a few fast jumps or lifts on top. Weeks 4 and 8 are recovery weeks at half the sets so your body can absorb the work, and week 12 is a test week at half the sets: work up to your best clean set of 3-5 reps on the main lifts and stop when the bar slows or your form changes. No set goes to failure: stop each set with 1-2 good reps left, and add weight only when every rep is clean. There is no overhead pressing.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Strength – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Strength – Soccer'), '{"1":"Strength A: legs","2":"Strength B: upper body","3":"Easy spin + mobility","4":"Strength C: hips & hamstrings","5":"Strength D: back, trunk & grip","6":"Ride or rest","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Barbell Back Squat",3,"8-10",120,true],["Dumbbell Bulgarian Split Squat",3,"8-10 each leg",90,true],["Step-Up",3,"12-15 each leg",60,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Pallof Press",3,"12-15 each side",60,false],["Plank",3,"12-15",60,fals