nian Deadlift",3,"4-6",180,true],["Hip Thrust",3,"6-8",120,false],["Seated Leg Curl",3,"10-12",60,false],["Back Extension",3,"10-12",60,false],["Dead Bug",3,"10-12 each side",60,false],["Standing Calf Raise",3,"10-12",45,false]],"5":[["Weighted Pull-Up",3,"4-6",180,true],["Dumbbell Single-Arm Row",3,"6-8 each arm",120,false],["Decline Push-Up",3,"6-8",120,false],["Dumbbell Rear-Delt Fly",3,"10-12",60,false],["Cable Wood Chopper",3,"10-12 each side",60,false],["Bird Dog",3,"10-12 each side",60,false]]},"p3":{"1":[["Barbell Back Squat",4,"3-5",180,false],["Jump Squat",3,"3, light load, land softly",90,false],["Dumbbell Bulgarian Split Squat",3,"5-6 each leg",120,false],["Step-Up",3,"8-10 each leg",60,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg, fast up",45,false],["Pallof Press",3,"8-10 each side",60,false],["Plank",3,"8-10",60,false]],"2":[["Neutral-Grip Dumbbell Bench Press",4,"3-5",180,false],["Chest-Supported Row",3,"5-6",120,false],["Push-Up",3,"5-6",120,false],["Cable Seated Rope Face Pull",3,"8-10",60,false],["Hammer Curl",3,"8-10",60,false],["Dumbbell Rear-Delt Fly",3,"8-10",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Romanian Deadlift",4,"3-5",180,false],["Hip Thrust",3,"5-6",120,false],["Seated Leg Curl",3,"8-10",60,false],["Back Extension",3,"8-10",60,false],["Dead Bug",3,"8-10 each side",60,false],["Standing Calf Raise",3,"8-10, fast up",45,false]],"5":[["Weighted Pull-Up",4,"3-5",180,false],["Dumbbell Single-Arm Row",3,"5-6 each arm",120,false],["Decline Push-Up",3,"5-6",120,false],["Dumbbell Rear-Delt Fly",3,"8-10",60,false],["Cable Wood Chopper",3,"8-10 each side",60,false],["Bird Dog",3,"8-10 each side",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Endurance – Cycling', 'For Cycling: a 12-week endurance program. Cycling endurance is built on a big aerobic base, then threshold work to raise the pace you can hold. The program builds long, easy rides first, then threshold and VO2 intervals, and keeps a little strength work so your legs and back hold up. Each week has 6 sessions: Monday zone 2 base, Tuesday intervals, Wednesday a short full-body strength session to keep your strength and protect your joints, Thursday tempo or threshold work, Friday easy recovery and mobility, and a long easy session on Saturday. Sunday is full rest. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds the aerobic base with short, light intervals. Block 2 (weeks 5-7) adds threshold work. Block 3 (weeks 9-11) adds harder, sport-specific intervals. The easy sessions get a little longer each block, and the interval rounds go up each week. Weeks 4 and 8 are recovery weeks with shorter easy sessions and half the intervals and strength sets. Week 12 is a test week: easy sessions, then a steady hard test on Tuesday so you can see how far you have come. Zone 2 means an easy pace where you can still chat. The hard efforts are about 8-9 out of 10 and the easy ones feel truly easy: most of your gains come from the easy days.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Endurance – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Endurance – Soccer'), '{"1":"Aerobic base: zone 2","2":"Intervals","3":"Strength maintenance (full body)","4":"Tempo and threshold","5":"Easy recovery + mobility","6":"Long session","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Steady State Ride",1,"60 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Cycling Intervals",5,"1 min at 8/10, 2 min easy spin between",120,true]],"3":[["Barbell Back Squat",2,"8-10",120,false],["Romanian Deadlift",2,"8-10",120,false],["Dumbbell Bulgarian Split Squat",2,"8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"40 sec",30,false]],"4":[["Indoor Cycling Spin",1,"45 min steady at a comfortable cadence",60,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Steady State Ride",1,"90 min easy: zone 2, a pace where you can talk",60,false]]},"p2":{"1":[["Steady State Ride",1,"75 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Cycling Intervals",3,"5 min at 8/10 (threshold), 4 min easy spin between",240,true]],"3":[["Barbell Back Squat",2,"6-8",120,false],["Romanian Deadlift",2,"6-8",120,false],["Dumbbell Bulgarian Split Squat",2,"6-8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false]],"4":[["Cycling Intervals",2,"12 min at 7/10: comfortably hard (tempo), 5 min easy between",300,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Steady State Ride",1,"120 min easy: zone 2, a pace where you can talk",60,false]]},"p3":{"1":[["Steady State Ride",1,"90 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Cycling Intervals",4,"4 min at 9/10, 4 min easy spin between",240,false]],"3":[["Barbell Back Squat",2,"5-6",150,false],["Romanian Deadlift",2,"5-6",150,false],["Dumbbell Bulgarian Split Squat",2,"6 each leg",90,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false]],"4":[["Cycling Intervals",3,"8 min at 8/10, 4 min easy between",240,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Steady State Ride",1,"150 min easy: zone 2, a pace where you can talk",60,false]]},"r1":{"1":[["Steady State Ride",1,"36 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Steady State Ride",1,"54 min easy: zone 2, a pace where you can talk",60,false]],"4":[["Indoor Cycling Spin",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r2":{"1":[["Steady State Ride",1,"45 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Steady State Ride",1,"72 min easy: zone 2, a pace where you can talk",60,false]],"4":[["Indoor Cycling Spin",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r3":{"1":[["Steady State Ride",1,"54 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Steady State Ride",1,"90 min easy: zone 2, a pace where you can talk",60,false]],"2":[["Cycling Intervals",1,"Test: 20 min at a steady hard effort. Note your distance or average power",60,false]],"4":[["Indoor Cycling Spin",1,"20 min easy: stay loose before your test",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Speed – Cycling', 'For Cycling: a 12-week speed program. Cycling speed is sprint power and a fast, smooth cadence. The program builds explosive leg and hip power in the gym, and short all-out sprints and fast spin-ups on the bike. Monday is a lower body strength and jump session, Tuesday is a bike sprint session, Wednesday an easy spin with mobility, Thursday fast spin-ups or surges on the bike and Friday power and trunk work. Saturday is your normal ride or a rest and Sunday is full rest. It runs in three 4-week blocks. Block 1 (weeks 1-3) learns good mechanics and builds a base at 8 out of 10 effort, so tendons and hamstrings are ready. Block 2 (weeks 5-7) goes all-out on acceleration and adds fast, springy work. Block 3 (weeks 9-11) peaks with the fastest efforts and the most reactive work. Weeks 4 and 8 are recovery weeks at half the sets, and week 12 is a test week at half the sets: test a 20 m sprint and a broad jump (or your best sprint on the bike) and compare with week 1. Rest fully between sprints: speed work is quality, not tiring conditioning, so stop the session if your form slips or a hamstring feels tight. No set goes to failure, and depth jumps are from a low box only.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Speed – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Speed – Soccer'), '{"3":"Active recovery: zone 2 + mobility","6":"Play your sport or rest","7":"Full rest","1":"Strength & jumps: lower body","2":"Sprint session (bike)","4":"Cadence & surges (bike)","5":"Power & trunk"}'::jsonb, '{"p1":{"1":[["Barbell Back Squat",3,"5-6",150,true],["Jump Squat",3,"4, light load, land softly",90,false],["Hip Thrust",3,"8",90,false],["Dumbbell Bulgarian Split Squat",3,"6-8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"12 each leg",45,false],["Plank",2,"40 sec",30,false]],"2":[["Cycling Sprint",5,"8 sec out of the saddle, all-out from a slow roll, 3 min easy between",180,true]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Cycling Intervals",5,"10 sec fast spin-up, 110 rpm or more, smooth not bouncing, 2 min easy between",120,true]],"5":[["Kettlebell Swing",3,"10, hips snap, arms relaxed",90,false],["Medicine Ball Slam",3,"8",60,false],["Pull-Up",3,"6-8",90,false],["Push-Up",3,"10-12",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]]},"p2":{"1":[["Barbell Back Squat",3,"3-5",180,true],["Jump Squat",4,"4, light load, fast",90,false],["Romanian Deadlift",3,"5",120,false],["Box Jump",3,"3, step down",90,false],["Single-Leg Standing Calf Raise",3,"10 each leg",45,false],["Dead Bug",2,"8 each side",30,false]],"2":[["Cycling Sprint",6,"10 sec out of the saddle, all-out from a slow roll, 3 min easy between",180,true]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Cycling Intervals",5,"15 sec fast spin-up, 120 rpm or more, 2 min easy between",120,true]],"5":[["Kettlebell Swing",4,"8, fast",90,false],["Medicine Ball Slam",3,"6, hard",60,false],["Weighted Pull-Up",3,"5-6",120,false],["Push-Up",3,"10",60,false],["Cable Wood Chopper",3,"10 each side",45,false],["Bird Dog",2,"8 each side",30,false]]},"p3":{"1":[["Barbell Back Squat",4,"3",180,false],["Jump Squat",4,"4, light load, fast",90,false],["Hip Thrust",3,"6, fast up",90,false],["Box Jump",4,"3, step down",90,false],["Single-Leg Standing Calf Raise",3,"8 each leg, fast up",45,false],["Dead Bug",2,"8 each side",30,false]],"2":[["Cycling Sprint",6,"12 sec all-out from a slow roll, 4 min easy between",240,true]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Cycling Intervals",5,"20 sec fast spin-up, 120 rpm or more, 2 min easy between",120,true]],"5":[["Kettlebell Swing",4,"6, fast",90,false],["Medicine Ball Slam",3,"5, hard",60,false],["Weighted Pull-Up",3,"5",120,false],["Push-Up",3,"10",60,false],["Cable Wood Chopper",3,"8 each side",45,false],["Dead Bug",2,"8 each side",30,false]]}}'::jsonb);
select public.add_sport_block('12-Week Strength – Mountain Biking', 'For Mountain Biking: a 12-week strength program. Mountain biking needs strong legs for punchy climbs, and an upper body, grip and core that control the bike on rough descents. The program builds leg and hip power, a strong back and core, and grip and upper body strength for hanging on. Four strength sessions a week (Monday lower body, Tuesday upper body, Thursday hips and hamstrings, Friday upper body and trunk) train every muscle twice a week, with an easy zone 2 and mobility session on Wednesday, your sport or rest on Saturday and a full rest on Sunday. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds muscle and tendon strength at 8-10 reps with sets going up each week. Block 2 (weeks 5-7) gets heavier at 4-6 reps. Block 3 (weeks 9-11) peaks strength at 3-5 reps with a few fast jumps or lifts on top. Weeks 4 and 8 are recovery weeks at half the sets so your body can absorb the work, and week 12 is a test week at half the sets: work up to your best clean set of 3-5 reps on the main lifts and stop when the bar slows or your form changes. No set goes to failure: stop each set with 1-2 good reps left, and add weight only when every rep is clean. There is no overhead pressing.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Strength – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Strength – Soccer'), '{"1":"Strength A: legs","2":"Strength B: upper body","3":"Easy spin + mobility","4":"Strength C: hips & hamstrings","5":"Strength D: back, trunk & grip","6":"Ride or rest","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Barbell Back Squat",3,"8-10",120,true],["Dumbbell Bulgarian Split Squat",3,"8-10 each leg",90,true],["Walking Lunge",3,"12-15 each leg",60,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Pallof Press",3,"12-15 each side",60,false],["Plank",3,"12-15",60,false]],"2":[["Bench Press",3,"8-10",120,true],["Chest-Supported Row",3,"8-10",90,true],["Incline Dumbbell Press",3,"8-10",90,true],["Cable Seated Rope Face Pull",3,"12-15",60,false],["Hammer Curl",3,"12-15",60,false],["Cable Rope Pushdown",3,"12-15",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Romanian Deadlift",3,"8-10",120,true],["Hip Thrust",3,"8-10",90,true],["Seated Leg Curl",3,"12-15",60,false],["Back Extension",3,"12-15",60,false],["Single-Leg Romanian Deadlift",3,"12-15 each leg",60,false],["Dead Bug",3,"12-15 each side",60,false]],"5":[["Pull-Up",3,"8-10",120,true],["Dumbbell Single-Arm Row",3,"8-10 each arm",90,true],["Neutral-Grip Dumbbell Bench Press",3,"8-10",90,true],["Dead Hang",2,"20-30 sec",60,false],["Dumbbell Farmer''s Carry",2,"30 m",60,false],["Cable Wood Chopper",3,"12-15 each side",60,false]]},"p2":{"1":[["Barbell Back Squat",3,"4-6",180,true],["Dumbbell Bulgarian Split Squat",3,"6-8 each leg",120,false],["Walking Lunge",3,"10-12 each leg",60,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Pallof Press",3,"10-12 each side",60,false],["Plank",3,"10-12",60,false]],"2":[["Bench Press",3,"4-6",180,true],["Chest-Supported Row",3,"6-8",120,false],["Incline Dumbbell Press",3,"6-8",120,false],["Cable Seated Rope Face Pull",3,"10-12",60,false],["Hammer Curl",3,"10-12",60,false],["Cable Rope Pushdown",3,"10-12",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Romanian Deadlift",3,"4-6",180,true],["Hip Thrust",3,"6-8",120,false],["Seated Leg Curl",3,"10-12",60,false],["Back Extension",3,"10-12",60,false],["Single-Leg Romanian Deadlift",3,"10-12 each leg",60,false],["Dead Bug",3,"10-12 each side",60,false]],"5":[["Weighted Pull-Up",3,"4-6",180,true],["Dumbbell Single-Arm Row",3,"6-8 each arm",120,false],["Neutral-Grip Dumbbell Bench Press",3,"6-8",120,false],["Dead Hang",2,"30-40 sec",60,false],["Dumbbell Farmer''s Carry",3,"30 m",60,false],["Cable Wood Chopper",3,"10-12 each side",60,false]]},"p3":{"1":[["Barbell Back Squat",4,"3-5",180,false],["Jump Squat",3,"3, light load, land softly",90,false],["Dumbbell Bulgarian Split Squat",3,"5-6 each leg",120,false],["Walking Lunge",3,"8-10 each leg",60,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg, fast up",45,false],["Pallof Press",3,"8-10 each side",60,false],["Plank",3,"8-10",60,false]],"2":[["Bench Press",4,"3-5",180,false],["Chest-Supported Row",3,"5-6",120,false],["Incline Dumbbell Press",3,"5-6",120,false],["Cable Seated Rope Face Pull",3,"8-10",60,false],["Hammer Curl",3,"8-10",60,false],["Cable Rope Pushdown",3,"8-10",60,false]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Romanian Deadlift",4,"3-5",180,false],["Hip Thrust",3,"5-6",120,false],["Seated Leg Curl",3,"8-10",60,false],["Back Extension",3,"8-10",60,false],["Single-Leg Romanian Deadlift",3,"8-10 each leg",60,false],["Dead Bug",3,"8-10 each side",60,false]],"5":[["Weighted Pull-Up",4,"3-5",180,false],["Dumbbell Single-Arm Row",3,"5-6 each arm",120,false],["Neutral-Grip Dumbbell Bench Press",3,"5-6",120,false],["Dead Hang",2,"30-45 sec, stop before your grip gives",60,false],["Dumbbell Farmer''s Carry",3,"40 m",60,false],["Cable Wood Chopper",3,"8-10 each side",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Endurance – Mountain Biking', 'For Mountain Biking: a 12-week endurance program. Mountain biking is long days of climbing with hard bursts over roots and rocks. The program builds a big aerobic base, climbing intervals and punchy efforts, with a long trail ride on Saturday and strength work to keep your back, core and grip strong. Each week has 6 sessions: Monday zone 2 base, Tuesday intervals, Wednesday a short full-body strength session to keep your strength and protect your joints, Thursday tempo or threshold work, Friday easy recovery and mobility, and a long easy session on Saturday. Sunday is full rest. It runs in three 4-week blocks. Block 1 (weeks 1-3) builds the aerobic base with short, light intervals. Block 2 (weeks 5-7) adds threshold work. Block 3 (weeks 9-11) adds harder, sport-specific intervals. The easy sessions get a little longer each block, and the interval rounds go up each week. Weeks 4 and 8 are recovery weeks with shorter easy sessions and half the intervals and strength sets. Week 12 is a test week: easy sessions, then a steady hard test on Tuesday so you can see how far you have come. Zone 2 means an easy pace where you can still chat. The hard efforts are about 8-9 out of 10 and the easy ones feel truly easy: most of your gains come from the easy days.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Endurance – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Endurance – Soccer'), '{"1":"Aerobic base: zone 2","2":"Intervals","3":"Strength maintenance (full body)","4":"Tempo and threshold","5":"Easy recovery + mobility","6":"Long session","7":"Full rest"}'::jsonb, '{"p1":{"1":[["Steady State Ride",1,"60 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Cycling Intervals",5,"1 min at 8/10, 2 min easy spin between",120,true]],"3":[["Barbell Back Squat",2,"8-10",120,false],["Romanian Deadlift",2,"8-10",120,false],["Dumbbell Bulgarian Split Squat",2,"8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"12-15 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"40 sec",30,false]],"4":[["Trail Run",1,"30 min easy: cross-training to spare your bike legs",60,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Steady State Ride",1,"90 min easy: zone 2, a pace where you can talk",60,false]]},"p2":{"1":[["Steady State Ride",1,"75 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Cycling Intervals",3,"5 min climbing at 8/10, 4 min easy between",240,true]],"3":[["Barbell Back Squat",2,"6-8",120,false],["Romanian Deadlift",2,"6-8",120,false],["Dumbbell Bulgarian Split Squat",2,"6-8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"10-12 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false]],"4":[["Cycling Intervals",2,"10 min at 7/10: comfortably hard (tempo), 4 min easy between",240,false]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Steady State Ride",1,"120 min easy: zone 2, a pace where you can talk",60,false]]},"p3":{"1":[["Steady State Ride",1,"90 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"2":[["Cycling Intervals",4,"3 min climbing at 9/10, 3 min easy between",180,false]],"3":[["Barbell Back Squat",2,"5-6",150,false],["Romanian Deadlift",2,"5-6",150,false],["Dumbbell Bulgarian Split Squat",2,"6 each leg",90,false],["Single-Leg Standing Calf Raise",3,"8-10 each leg",45,false],["Pull-Up",2,"6-8",90,false],["Push-Up",2,"10-12",60,false],["Plank",2,"45 sec",30,false]],"4":[["Cycling Sprint",6,"10 sec out of the saddle, as if jumping a trail obstacle, 2 min easy between",120,true]],"5":[["Steady State Ride",1,"20 min very easy spin or walk: loosen up, no effort",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false]],"6":[["Steady State Ride",1,"150 min easy: zone 2, a pace where you can talk",60,false]]},"r1":{"1":[["Steady State Ride",1,"36 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Steady State Ride",1,"54 min easy: zone 2, a pace where you can talk",60,false]],"4":[["Trail Run",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r2":{"1":[["Steady State Ride",1,"45 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Steady State Ride",1,"72 min easy: zone 2, a pace where you can talk",60,false]],"4":[["Trail Run",1,"15 min steady: comfortable pace, keep it easy",60,false]]},"r3":{"1":[["Steady State Ride",1,"54 min zone 2: easy pace you could chat at",60,false],["Plank",2,"40 sec",30,false],["Bird Dog",2,"8 each side",30,false]],"6":[["Steady State Ride",1,"90 min easy: zone 2, a pace where you can talk",60,false]],"2":[["Cycling Intervals",1,"Test: 20 min climb at a steady hard effort. Note the distance or time",60,false]],"4":[["Trail Run",1,"20 min easy: stay loose before your test",60,false]]}}'::jsonb);
select public.add_sport_block('12-Week Speed – Mountain Biking', 'For Mountain Biking: a 12-week speed program. Mountain bike speed is punchy power out of corners and up short climbs. The program builds explosive hips and legs in the gym, and short sprints, surges and fast spin-ups on the bike. Monday is a lower body strength and jump session, Tuesday is a bike sprint session, Wednesday an easy spin with mobility, Thursday fast spin-ups or surges on the bike and Friday power and trunk work. Saturday is your normal ride or a rest and Sunday is full rest. It runs in three 4-week blocks. Block 1 (weeks 1-3) learns good mechanics and builds a base at 8 out of 10 effort, so tendons and hamstrings are ready. Block 2 (weeks 5-7) goes all-out on acceleration and adds fast, springy work. Block 3 (weeks 9-11) peaks with the fastest efforts and the most reactive work. Weeks 4 and 8 are recovery weeks at half the sets, and week 12 is a test week at half the sets: test a 20 m sprint and a broad jump (or your best sprint on the bike) and compare with week 1. Rest fully between sprints: speed work is quality, not tiring conditioning, so stop the session if your form slips or a hamstring feels tight. No set goes to failure, and depth jumps are from a low box only.', (select nutrition from public.programs where trainer_id is null and name = '12-Week Speed – Soccer'), (select warm_up from public.programs where trainer_id is null and name = '12-Week Speed – Soccer'), '{"3":"Active recovery: zone 2 + mobility","6":"Play your sport or rest","7":"Full rest","1":"Strength & jumps: lower body","2":"Sprint session (bike)","4":"Cadence & surges (bike)","5":"Power & trunk"}'::jsonb, '{"p1":{"1":[["Barbell Back Squat",3,"5-6",150,true],["Jump Squat",3,"4, light load, land softly",90,false],["Hip Thrust",3,"8",90,false],["Dumbbell Bulgarian Split Squat",3,"6-8 each leg",90,false],["Single-Leg Standing Calf Raise",3,"12 each leg",45,false],["Plank",2,"40 sec",30,false]],"2":[["Cycling Sprint",5,