 Raise",3,"8 each leg, fast up",45,false],["Dead Bug",2,"8 each side",30,false]],"2":[["Cycling Sprint",6,"12 sec all-out from a slow roll, 4 min easy between",240,true]],"3":[["Steady State Ride",1,"25-35 min zone 2: easy pace you could chat at",60,false],["World''s Greatest Stretch",2,"5 each side",30,false],["90/90 Hip Switch",2,"8 each side",30,false],["Thoracic Open Book",2,"8 each side",30,false],["Couch Stretch",2,"45 sec each side",30,false],["Dead Bug",2,"8 each side, slow",30,false]],"4":[["Cycling Sprint",5,"30 sec punchy climb at 9/10, 3 min easy between",180,true]],"5":[["Kettlebell Swing",4,"6, fast",90,false],["Medicine Ball Slam",3,"5, hard",60,false],["Weighted Pull-Up",3,"5",120,false],["Push-Up",3,"10",60,false],["Cable Wood Chopper",3,"8 each side",45,false],["Dead Bug",2,"8 each side",30,false]]}}'::jsonb);
